export default async function Home({
  searchParams,
}: {
  searchParams: Promise<{ auth_error?: string; workspace?: string | string[] }>;
}) {
  const { auth_error, workspace } = await searchParams;

  return <HomeShell authError={auth_error === "1"} workspaceId={typeof workspace === "string" ? workspace : undefined} />;
