@import "tailwindcss";

@theme inline {
  --font-title: var(--font-bespoke-stencil), Georgia, serif;
  --font-serif: var(--font-source-serif-4), Georgia, serif;
  --color-background: #362a4a;
  --color-surface: #40344f;
  --color-foreground: #f6f0e6;
  --color-muted: #c8bdcf;
  --color-accent: #e6b5a0;
  --color-border: #756581;
  --color-danger: #ffb5b8;
  --text-display: clamp(3.5rem, 8vw, 7rem);
  --text-display--line-height: 1;
  --text-heading: clamp(2rem, 4vw, 3.5rem);
  --text-heading--line-height: 1.1;
  --radius-panel: 1rem;
  --radius-control: 0.5rem;
}

@layer base {
  html {
    color-scheme: dark;
  }

  body {
    background: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-serif);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
  }

  h1, h2, h3, h4, h5, h6, [role="heading"] {
    font-family: var(--font-title);
    font-weight: 400;
    font-style: normal;
    font-synthesis: none;
    line-height: 1.15;
    text-wrap: balance;
  }

  h1 { font-size: var(--text-display); }
  h2 { font-size: var(--text-heading); }
  h3 { font-size: 1.75rem; }
  h4 { font-size: 1.5rem; }
  h5 { font-size: 1.25rem; }
  h6 { font-size: 1.125rem; }

  ::selection {
    background: var(--color-accent);
    color: var(--color-background);
  }

  :focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 4px;
  }
}

@layer components {
  .home-intro .home-reveal {
    animation: home-text-reveal 900ms ease-in-out both;
    animation-play-state: paused;
  }

  .home-intro p.home-reveal { animation-delay: 120ms; }

  .home-intro .home-sign-in { animation-delay: 240ms; }

  .home-intro[data-complete="true"] .home-reveal { animation-play-state: running; }

  .workspace-sidebar {
    animation: workspace-slide-in 600ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }

  .workspace-content {
    animation: workspace-fade-in 650ms cubic-bezier(0.22, 1, 0.36, 1) 120ms both;
  }

  .title {
    font-family: var(--font-title);
    font-weight: 400;
    font-style: normal;
    font-synthesis: none;
    line-height: 1.1;
    text-wrap: balance;
  }

  .eyebrow {
    font-size: 0.75rem;
    font-weight: 500;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--color-accent);
  }

  .surface {
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-panel);
  }

  .button {
    display: inline-flex;
    min-height: 2.75rem;
    align-items: center;
    justify-content: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border: 1px solid transparent;
    border-radius: var(--radius-control);
    background: var(--color-foreground);
    color: var(--color-background);
    font-size: 0.875rem;
    font-weight: 500;
    line-height: 1.25;
    cursor: pointer;
    transition: background-color 160ms ease;
  }

  .button:hover:not(:disabled) {
    background: var(--color-accent);
  }

  .button:disabled {
    cursor: not-allowed;
    opacity: 0.6;
  }

  .input {
    width: 100%;
    min-height: 2.75rem;
    padding: 0.625rem 0.875rem;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-control);
    background: color-mix(in srgb, var(--color-background) 60%, transparent);
    color: var(--color-foreground);
    font-family: var(--font-serif);
