  protocols: { label: "Stimulus Protocols", title: "Give each question a method.", description: "Build repeatable experiments around neural drive and touch stimuli.", placeholder: "Saved stimulus protocols are coming soon. Keep run durations, drive presets, and timed touch events together for future experiments." },
  library: { label: "Reference Library", title: "Keep what informs your work.", description: "A place for model references, research papers, and notes.", placeholder: "Your reference library is coming soon. Saved papers and model documentation will live here." },
  questions: { label: "Research Questions", title: "Start with a question.", description: "Follow a research question from literature search to an experiment proposal.", placeholder: "Saved research questions are coming soon. Revisit agent progress, supporting papers, and the findings behind each proposed experiment." },
  proposals: { label: "Proposal Review", title: "Review before you run.", description: "Examine the evidence, protocol, and model limitations before approving a simulation.", placeholder: "Proposal review is coming soon. Review the exact experiment configuration and any unsupported inputs before approving or declining a run." },
