export default function HomeShell({ authError = false, workspaceId }: { authError?: boolean; workspaceId?: string }) {
  const [user, setUser] = useState<User | null>(null);
  const [active, setActive] = useState(workspaceId ? "launch" : "overview");
  const [selectedExperiment, setSelectedExperiment] = useState<ExperimentSession>();
  const [newExperimentId, setNewExperimentId] = useState<string>();
  const [linkedWorkspace, setLinkedWorkspace] = useState<{ userId: string; workspaceId: string; experiment?: ExperimentSession; error?: string }>();
  const userId = user?.id;
  useEffect(() => {
    if (!userId || !workspaceId) return;
    const controller = new AbortController();
    conversationRequest<ExperimentSession>(`/v1/workspaces/${encodeURIComponent(workspaceId)}`, { signal: controller.signal }).then(experiment => {
      if (!controller.signal.aborted) setLinkedWorkspace({ userId, workspaceId, experiment });
    }).catch(error => {
      if (!controller.signal.aborted) setLinkedWorkspace({ userId, workspaceId, error: error instanceof Error ? error.message : "Could not open this workspace." });
    });
    return () => controller.abort();
  }, [userId, workspaceId]);
  const openingLink = Boolean(workspaceId && !selectedExperiment && !newExperimentId);
  const linked = linkedWorkspace?.userId === userId && linkedWorkspace?.workspaceId === workspaceId ? linkedWorkspace : undefined;
  const experiment = selectedExperiment ?? (openingLink ? linked?.experiment : undefined);
  const [introComplete, setIntroComplete] = useState(false);
  const [dishReady, setDishReady] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(!workspaceId);
  const view = views[active];
  const onUserChange = useCallback((next: User | null) => {
    setUser(previous => {
      if (previous && previous.id !== next?.id) {
        try { localStorage.removeItem(selectionKey(previous.id)); } catch { /* Storage is optional. */ }
      }
      return next;
    });
  }, []);
  const section = navigation.find(item => item.children?.some(child => child.value === active))?.label;

  return (
    <div className="relative isolate flow-root min-h-dvh">
      <div className="pointer-events-none fixed inset-0 -z-10 bg-background">
        {dishReady || user ? <HomeBackground quiet={Boolean(user)} onIntroComplete={() => setIntroComplete(true)} /> : null}
      </div>
      {user ? (
        <a href="#workspace-content" className="button fixed left-6 top-6 z-40 -translate-y-32 focus:translate-y-0">
          Skip to content
        </a>
      ) : null}
      {user ? (
        <button
          type="button"
          className="button workspace-sidebar-toggle absolute left-6 top-4 z-30 size-11 !p-0 lg:fixed lg:top-10"
          aria-label={sidebarOpen ? "Hide sidebar" : "Show sidebar"}
          aria-expanded={sidebarOpen}
          aria-controls="workspace-sidebar"
          data-overlay={active === "launch"}
          onClick={() => setSidebarOpen(open => !open)}
        >
          <svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
            <path d="m14 6-6 6 6 6" />
          </svg>
        </button>
      ) : null}
      <div role={user ? undefined : "main"} data-complete={introComplete && (Boolean(user) || dishReady)} className={user
        ? "contents"
        : "home-intro home-landing"}>
        {!user ? <div aria-hidden="true" className="home-petri-dish home-reveal"><PetriDish onReady={setDishReady} playing={introComplete} /></div> : null}
        {user ? (
          <div className="workspace-sidebar-frame relative z-10 mx-6 w-[17rem] max-w-[calc(100%-3rem)] lg:fixed lg:top-6 lg:left-6 lg:mx-0" data-open={sidebarOpen} data-overlay={active === "launch"}>
          <aside id="workspace-sidebar" aria-hidden={!sidebarOpen} inert={!sidebarOpen} className="workspace-sidebar flex min-h-0 flex-col overflow-hidden rounded-panel border border-border/40 bg-background/85 font-semibold shadow-xl outline outline-offset-2 outline-accent/35 backdrop-blur-xl">
            <div className="workspace-sidebar-menu min-h-0 flex-1 overflow-y-auto px-4 pt-4">
            <p className="title text-left text-4xl">Anima Labs</p>
            <div className="mt-3">
              <button type="button" className="button workspace-launch mb-2 w-full" aria-current={active === "launch" ? "page" : undefined} onClick={() => {
                setSelectedExperiment(undefined);
                setNewExperimentId(crypto.randomUUID());
                setActive("launch");
                setSidebarOpen(false);
              }}>
                <svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" className="shrink-0">
                  <circle cx="12" cy="12" r="9" />
                  <path d="M12 8v8M8 12h8" />
                </svg>
                <span>Launch Experiment</span>
              </button>
              <BranchedMenu items={navigation} defaultOpen={[0]} active={active} onSelect={value => { if (value !== "experiments") setActive(value); }} fontSize={14} rowHeight={36} width={240} className="[&_.button]:!min-h-9 [&_.button]:!font-semibold [&_.branched-menu__head]:!py-1 [&_.branched-menu__head]:!text-sm" />
            </div>
            </div>
            <div className="shrink-0 p-4 pt-3">
              <GoogleSignInButton authError={authError} onUserChange={onUserChange} />
            </div>
          </aside>
          </div>
        ) : (
          <header>
            <h1 className="home-reveal text-[clamp(3.575rem,10.4vw,7.8rem)] leading-none">Anima Labs</h1>
            <p className="home-reveal mt-3 text-[2.34rem] text-muted sm:text-[2.808rem]">Agentic C. Elegans Research</p>
          </header>
        )}
        {user ? <ExperimentHistory key={user.id} onSelect={experiment => {
          setSelectedExperiment(experiment);
          setNewExperimentId(undefined);
          setActive("launch");
          setSidebarOpen(false);
        }} /> : null}
        {user ? (
          <main id="workspace-content" tabIndex={-1} className={`workspace-content relative z-0 ${active === "launch" ? "flex min-h-dvh items-center px-6 pb-36 pt-24 sm:px-12" : active === "overview" ? "min-h-dvh px-4 pb-12 pt-8 sm:px-8 lg:pt-24" : "px-8 pb-72 pt-24 text-2xl lg:px-16 lg:pt-24"} font-semibold ${sidebarOpen && active !== "launch" ? "lg:ml-[18.5rem]" : ""}`}>
            {active === "launch" ? openingLink && !experiment ? <p role={linked?.error ? "alert" : "status"} className="mx-auto text-muted">{linked?.error || "Opening your workspace…"}</p> : <ExperimentWorkspace key={`${user.id}:${experiment?.record_id || newExperimentId}`} user={user} experiment={experiment} newExperimentId={newExperimentId} /> : active === "overview" ? <OverviewDashboard key={user.id} userId={user.id} /> : active === "recurring" ? <RecurringResearch key={user.id} /> : <>
            <p className="eyebrow mb-8 text-lg font-semibold">{section} / {view.label}</p>
            <div aria-live="polite">
              <h1 className="text-[clamp(3rem,14vw,3.75rem)] xl:text-8xl">{view.title}</h1>
              <p className="mt-6 max-w-xl text-muted">
                {view.description}
              </p>
            </div>
            {view.placeholder ? (
              <section className="surface mt-12 max-w-2xl p-8">
                <p className="eyebrow">Coming soon</p>
                <h2 className="mt-4 text-3xl">{view.label}</h2>
                <p className="mt-4 text-lg text-muted">{view.placeholder}</p>
              </section>
            ) : null}
            </>}
          </main>
        ) : null}
        {!user ? <div className="hidden">
          <GoogleSignInButton authError={authError} onUserChange={onUserChange} />
        </div> : null}
      </div>
    </div>
  );
}
.workspace-sidebar-frame {
  display: grid;
  grid-template-rows: 1fr;
  height: calc(100dvh - 6.5rem);
  max-height: calc(100dvh - 6.5rem);
  margin-block: 5rem 1.5rem;
  transition:
    transform 400ms ease,
    opacity 400ms ease,
    grid-template-rows 400ms ease,
    margin 400ms ease,
    visibility 400ms;
}

.workspace-sidebar-frame[data-open="false"] {
  grid-template-rows: 0fr;
  height: 0;
  margin-block: 0;
  transform: translateX(calc(-100% - 1.5rem));
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.button.workspace-sidebar-toggle,
.button.workspace-sidebar-toggle:hover:not(:disabled) {
  border: 0;
  background: transparent;
  color: var(--color-foreground);
  box-shadow: none;
}

.workspace-sidebar-toggle {
  transition: transform 400ms ease;
}

.workspace-sidebar-toggle svg {
  transition: transform 400ms ease;
}

.workspace-sidebar-toggle[aria-expanded="false"] svg {
  transform: rotate(180deg);
}

.workspace-content {
  transition: margin-left 400ms ease;
}

.workspace-sidebar-frame[data-overlay="true"] {
  position: fixed;
  inset: 5rem auto auto 1.5rem;
  grid-template-rows: 1fr;
  margin: 0;
}

.workspace-sidebar-toggle[data-overlay="true"] {
  position: fixed;
}

@media (min-width: 1024px) {
  .workspace-sidebar-frame[data-overlay="true"] {
    top: 1.5rem;
  }

  .workspace-sidebar-frame,
  .workspace-sidebar-frame[data-open="false"] {
    grid-template-rows: 1fr;
    margin-block: 0;
    height: calc(100dvh - 3rem);
    max-height: calc(100dvh - 3rem);
  }

  .workspace-sidebar-toggle[aria-expanded="true"] {
    transform: translateX(17.5rem);
  }
}

@media (prefers-reduced-motion: reduce) {
  .workspace-sidebar-frame,
  .workspace-sidebar-toggle,
