"use client";

import { useEffect, useRef } from "react";
import { Group, Mesh, MeshPhysicalMaterial, OrthographicCamera, PMREMGenerator, Scene, TorusGeometry, Vector3, WebGLRenderer } from "three";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
import { RoomEnvironment } from "three/addons/environments/RoomEnvironment.js";
import { createWormPreview } from "@/lib/worm-preview";

export default function PetriDish({ onReady, playing }: { onReady: (ready: boolean) => void; playing: boolean }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const playingRef = useRef(playing);
  const updatePlaybackRef = useRef(() => {});

  useEffect(() => {
    playingRef.current = playing;
    updatePlaybackRef.current();
  }, [playing]);

  useEffect(() => {
    let cleanup: (() => void) | undefined;
    // Let Strict Mode cancel its trial effect before allocating a second GPU renderer.
    const startFrame = requestAnimationFrame(() => {
      const canvas = canvasRef.current!;
      let renderer: WebGLRenderer;
      try {
        renderer = new WebGLRenderer({ canvas, alpha: true, antialias: true });
      } catch {
        onReady(true);
        return;
      }

      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      const scene = new Scene();
      const plate = new Group();
      // The source lies in XY: present its face 30° above horizontal toward the camera.
      plate.rotation.x = -Math.PI / 3;
      scene.add(plate);
      const rim = new Mesh(new TorusGeometry(0.985, 0.012, 12, 128), new MeshPhysicalMaterial({
        color: getComputedStyle(canvas).getPropertyValue("--color-foreground").trim(),
        transparent: true, opacity: 0.6, roughness: 0.2, clearcoat: 1, depthWrite: false,
      }));
      const preview = createWormPreview();
      const worm = new Mesh(preview.geometry, new MeshPhysicalMaterial({
        color: getComputedStyle(canvas).getPropertyValue("--color-accent").trim(),
        roughness: 0.35,
        clearcoat: 0.4,
      }));
      const camera = new OrthographicCamera(-1.2, 1.2, 0.8, -0.8, 0.1, 10);
      camera.position.z = 4;
      const room = new RoomEnvironment();
      const pmrem = new PMREMGenerator(renderer);
      const environment = pmrem.fromScene(room, 0.04);
      scene.environment = environment.texture;
      room.dispose();
      pmrem.dispose();

      let disposed = false;
      let prepared = false;
      let dish: Mesh | undefined;
      const disposeDish = (mesh: Mesh) => {
        mesh.geometry.dispose();
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        materials.forEach(material => material.dispose());
      };
      const render = () => renderer.render(scene, camera);
      const resize = () => {
        const { width, height } = canvas.getBoundingClientRect();
        if (!width || !height) return;
        renderer.setSize(width, height, false);
        camera.top = 1.2 * height / width;
        camera.bottom = -camera.top;
        camera.updateProjectionMatrix();
        if (prepared) render();
      };
      const observer = new ResizeObserver(resize);
      observer.observe(canvas);
      const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
      let elapsed = 0;
      let previousTime: number | undefined;
      const animate = (time: number) => {
        if (previousTime !== undefined) elapsed += (time - previousTime) / 1000;
        previousTime = time;
        preview.update(elapsed);
        render();
      };
      const updatePlayback = () => {
        previousTime = undefined;
        renderer.setAnimationLoop(prepared && playingRef.current && !reducedMotion.matches && !document.hidden ? animate : null);
        if (prepared) render();
      };
      updatePlaybackRef.current = updatePlayback;
      reducedMotion.addEventListener("change", updatePlayback);
      document.addEventListener("visibilitychange", updatePlayback);

      const fail = (error: unknown) => {
        if (!disposed) {
          console.warn("Unable to load the decorative petri dish", error);
          onReady(true);
        }
      };
      new GLTFLoader().load("/models/petri-dish.glb", ({ scene: model }) => {
        dish = model.children[0] as Mesh;
        if (disposed) {
          disposeDish(dish);
          return;
        }
        dish.geometry.center();
        dish.geometry.computeBoundingBox();
        const size = dish.geometry.boundingBox!.getSize(new Vector3());
        dish.scale.setScalar(2 / size.x);
        const glass = dish.material as MeshPhysicalMaterial;
        glass.opacity = 0.45;
        glass.roughness = 0.08;
        glass.envMapIntensity = 1.2;
        glass.depthWrite = false;
