647	      let renderer: WebGLRenderer;
648	      try {
649	        renderer = new WebGLRenderer({ canvas, alpha: true, antialias: true });
650	      } catch {
651	        onReady(true);
652	        return;
653	      }
654	
655	      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
656	      const scene = new Scene();
657	      const plate = new Group();
658	      // The source lies in XY: present its face 30° above horizontal toward the camera.
659	      plate.rotation.x = -Math.PI / 3;
660	      scene.add(plate);
661	      const rim = new Mesh(new TorusGeometry(0.985, 0.012, 12, 128), new MeshPhysicalMaterial({
662	        color: getComputedStyle(canvas).getPropertyValue("--color-foreground").trim(),
663	        transparent: true, opacity: 0.6, roughness: 0.2, clearcoat: 1, depthWrite: false,
664	      }));
665	      const preview = createWormPreview();
666	      const worm = new Mesh(preview.geometry, new MeshPhysicalMaterial({
667	        color: getComputedStyle(canvas).getPropertyValue("--color-accent").trim(),
668	        roughness: 0.35,
669	        clearcoat: 0.4,
670	      }));
671	      const camera = new OrthographicCamera(-1.2, 1.2, 0.8, -0.8, 0.1, 10);
672	      camera.position.z = 4;
673	      const room = new RoomEnvironment();
674	      const pmrem = new PMREMGenerator(renderer);
675	      const environment = pmrem.fromScene(room, 0.04);
676	      scene.environment = environment.texture;
677	      room.dispose();
678	      pmrem.dispose();
679	
680	      let disposed = false;
681	      let prepared = false;
682	      let dish: Mesh | undefined;
683	      const disposeDish = (mesh: Mesh) => {
684	        mesh.geometry.dispose();
685	        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
686	        materials.forEach(material => material.dispose());
687	      };
688	      const render = () => renderer.render(scene, camera);
