702	      let previousTime: number | undefined;
703	      const animate = (time: number) => {
704	        if (previousTime !== undefined) elapsed += (time - previousTime) / 1000;
705	        previousTime = time;
706	        preview.update(elapsed);
707	        render();
708	      };
709	      const updatePlayback = () => {
710	        previousTime = undefined;
711	        renderer.setAnimationLoop(prepared && playingRef.current && !reducedMotion.matches && !document.hidden ? animate : null);
712	        if (prepared) render();
713	      };
714	      updatePlaybackRef.current = updatePlayback;
715	      reducedMotion.addEventListener("change", updatePlayback);
716	      document.addEventListener("visibilitychange", updatePlayback);
717	
718	      const fail = (error: unknown) => {
719	        if (!disposed) {
720	          console.warn("Unable to load the decorative petri dish", error);
721	          onReady(true);
722	        }
723	      };
724	      new GLTFLoader().load("/models/petri-dish.glb", ({ scene: model }) => {
725	        dish = model.children[0] as Mesh;
726	        if (disposed) {
727	          disposeDish(dish);
728	          return;
729	        }
730	        dish.geometry.center();
731	        dish.geometry.computeBoundingBox();
732	        const size = dish.geometry.boundingBox!.getSize(new Vector3());
733	        dish.scale.setScalar(2 / size.x);
734	        const glass = dish.material as MeshPhysicalMaterial;
735	        glass.opacity = 0.45;
736	        glass.roughness = 0.08;
737	        glass.envMapIntensity = 1.2;
738	        glass.depthWrite = false;
