        container.removeChild(canvas);
      } catch {
        // Ignore
      }
    };
  }, [
    timeSpeed,
    colorBalance,
    warpStrength,
    warpFrequency,
    warpSpeed,
    warpAmplitude,
    blendAngle,
    blendSoftness,
    rotationAmount,
    noiseScale,
    grainAmount,
    grainScale,
    grainAnimated,
    contrast,
    gamma,
    saturation,
    centerX,
    centerY,
    zoom,
    colorsControllerRef
  ]);

  useEffect(() => {
    const api = colorsControllerRef?.current;
    if (!api?.setColors) return;
    api.setColors(color1, color2, color3);
  }, [color1, color2, color3, colorsControllerRef]);

  return (
    <div
      ref={containerRef}
      className={`relative h-full w-full overflow-hidden ${className}`.trim()} />
  );
};

