import { useEffect, useMemo, useRef, type RefObject } from 'react'
import { Canvas, useFrame, useThree } from '@react-three/fiber'
import * as THREE from 'three'
import { buildNeuron } from '../lib/neuron'
import { NeuronSim, glowTexture } from '../lib/neuron-sim'

export type NeuronHandle = { fire: () => void }

type Props = {
  /** Smoothed 0→1 "stain" progress, owned by the page. */
  progressRef: RefObject<number>
  handleRef: RefObject<NeuronHandle | null>
  /** Soma position as viewport fractions, for the ripple. */
  onSpike: (x: number, y: number) => void
  onInput: () => void
  reducedMotion: boolean
}

const FOV = 35

const dustVS = /* glsl */ `
attribute float aSeed;
uniform float uTime;
uniform float uScale;
varying float vSeed;
void main() {
  vSeed = aSeed;
  vec3 p = position;
  p.x += sin(uTime * 0.07 + aSeed * 40.0) * 0.6;
  p.y += cos(uTime * 0.05 + aSeed * 23.0) * 0.5;
  vec4 mv = modelViewMatrix * vec4(p, 1.0);
  gl_PointSize = (0.04 + aSeed * 0.07) * uScale / -mv.z;
  gl_Position = projectionMatrix * mv;
}`

const dustFS = /* glsl */ `
uniform sampler2D uMap;
uniform float uTime;
varying float vSeed;
void main() {
  float a = texture2D(uMap, gl_PointCoord).a;
  float twinkle = 0.55 + 0.45 * sin(uTime * (0.4 + vSeed) + vSeed * 90.0);
  gl_FragColor = vec4(vec3(0.75, 0.88, 1.0) * a * 0.22 * twinkle, 1.0);
  #include <colorspace_fragment>
}`

function Dust({ glow, reducedMotion }: { glow: THREE.Texture; reducedMotion: boolean }) {
  const { geo, mat } = useMemo(() => {
    const n = 420
    const pos = new Float32Array(n * 3)
    const seed = new Float32Array(n)
    for (let i = 0; i < n; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 44
      pos[i * 3 + 1] = (Math.random() - 0.5) * 26
      pos[i * 3 + 2] = -24 + Math.random() * 30
      seed[i] = Math.random()
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    geo.setAttribute('aSeed', new THREE.BufferAttribute(seed, 1))
    const mat = new THREE.ShaderMaterial({
      vertexShader: dustVS,
      fragmentShader: dustFS,
      uniforms: { uTime: { value: 0 }, uScale: { value: 600 }, uMap: { value: glow } },
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    })
    return { geo, mat }
  }, [glow])
  useEffect(() => () => { geo.dispose(); mat.dispose() }, [geo, mat])
  useFrame((s) => {
    if (!reducedMotion) mat.uniforms.uTime.value = s.clock.elapsedTime
    mat.uniforms.uScale.value = (s.size.height * s.viewport.dpr) / (2 * Math.tan((FOV * Math.PI) / 360))
  })
  return <points geometry={geo} material={mat} frustumCulled={false} />
}

function Scene({ progressRef, handleRef, onSpike, onInput, reducedMotion }: Props) {
  const { size, camera, gl } = useThree()
  const glow = useMemo(glowTexture, [])
  const main = useMemo(() => new NeuronSim(buildNeuron(7), { glow, autoInterval: reducedMotion ? 0 : 2.6 }), [glow, reducedMotion])
  const background = useMemo(
    () => [
      new NeuronSim(buildNeuron(31, { axonLength: 9 }), { glow, intensity: 0.22, autoInterval: reducedMotion ? 0 : 4.2, particles: 200 }),
      new NeuronSim(buildNeuron(58, { axonLength: 8, dendrites: 6 }), { glow, intensity: 0.16, autoInterval: reducedMotion ? 0 : 5.5, particles: 200 }),
    ],
    [glow, reducedMotion],
  )
  const rig = useRef<THREE.Group>(null)
  const hover = useRef(false)

  useEffect(() => {
    const v = new THREE.Vector3()
    main.onSpike = () => {
      main.group.getWorldPosition(v).project(camera)
      onSpike((v.x + 1) / 2, (1 - v.y) / 2)
    }
    main.onInput = onInput
    handleRef.current = { fire: () => main.fire() }
    return () => {
      handleRef.current = null
    }
  }, [main, camera, onSpike, onInput, handleRef])

  useEffect(() => () => { main.dispose(); background.forEach((b) => b.dispose()); glow.dispose() }, [main, background, glow])

  const wide = size.width / size.height > 1.1
  const layout = wide
    ? { position: [-2.4, 2.1, 0] as const, rotation: -0.3, scale: 1 }
    : { position: [-0.4, 4.2, 0] as const, rotation: -1.15, scale: 0.72 }

  useFrame((state, delta) => {
    const dt = Math.min(delta, 0.05)
    const p = progressRef.current ?? 0
    const pointScale = (state.size.height * state.viewport.dpr) / (2 * Math.tan((FOV * Math.PI) / 360))
    main.setPointScale(pointScale)
    main.update(dt, p)
    for (const b of background) {
      b.setPointScale(pointScale)
      b.update(dt, p)
    }
    if (rig.current && !reducedMotion) {
      const t = state.clock.elapsedTime
      const ty = Math.sin(t * 0.16) * 0.22 + state.pointer.x * 0.12
      const tx = Math.sin(t * 0.11) * 0.06 - state.pointer.y * 0.06
      rig.current.rotation.y += (ty - rig.current.rotation.y) * 0.04
      rig.current.rotation.x += (tx - rig.current.rotation.x) * 0.04
    }
  })

  const setHover = (on: boolean) => {
    hover.current = on
    gl.domElement.style.cursor = on ? 'pointer' : ''
  }

  return (
    <>
      <group ref={rig}>
        <group position={layout.position} rotation={[0, 0, layout.rotation]} scale={layout.scale}>
          <primitive object={main.group} />
          {/* Generous invisible hit target around the soma. */}
          <mesh
            onClick={(e) => {
              e.stopPropagation()
              main.fire()
            }}
            onPointerOver={() => setHover(true)}
            onPointerOut={() => setHover(false)}
          >
            <sphereGeometry args={[2, 16, 12]} />
            <meshBasicMaterial visible={false} />
          </mesh>
        </group>
      </group>
      <group position={[-13, -4.5, -16]} rotation={[0.3, 0.4, 0.7]}>
        <primitive object={background[0].group} />
      </group>
      <group position={[12, 6.5, -22]} rotation={[-0.2, -0.5, 2.6]}>
        <primitive object={background[1].group} />
      </group>
      <Dust glow={glow} reducedMotion={reducedMotion} />
    </>
  )
}

export default function NeuronCanvas(props: Props) {
  return (
    <Canvas
      flat
      dpr={[1, 2]}
      camera={{ position: [0, 0, 20], fov: FOV, near: 0.1, far: 100 }}
      gl={{ antialias: true, alpha: true, powerPreference: 'high-performance' }}
      aria-hidden
    >
      <Scene {...props} />
    </Canvas>
  )
}

import { useEffect, useRef, type RefObject } from 'react'

export type TraceHandle = { spike: () => void; input: () => void }

/**
 * Rolling whole-cell membrane-potential trace, oscilloscope style.
 * Timescale is stretched so a spike is legible at a glance; shape follows a
 * real AP: depolarise, overshoot, repolarise, after-hyperpolarise, recover.
 */

const WINDOW = 1.8 // seconds visible
const V_MIN = -92
const V_MAX = 48
const REST = -70
const THRESH = -55

function spikeDelta(dt: number) {
  if (dt < 0) return 0
  if (dt < 0.012) return 108 * (dt / 0.012) ** 2
  if (dt < 0.034) return 108 - 120 * ((dt - 0.012) / 0.022)
  return -12 * Math.exp(-(dt - 0.034) / 0.09)
}

function epspDelta(dt: number) {
  if (dt < 0) return 0
  return 9 * (Math.exp(-dt / 0.05) - Math.exp(-dt / 0.012))
}

function noise(t: number) {
  return 0.55 * Math.sin(t * 37.1) + 0.35 * Math.sin(t * 91.7 + 1.3) + 0.25 * Math.sin(t * 173.3 + 0.4)
}

export default function MembraneTrace({ handleRef, reducedMotion }: { handleRef: RefObject<TraceHandle | null>; reducedMotion: boolean }) {
  const canvasRef = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    const canvas = canvasRef.current!
    const ctx = canvas.getContext('2d')!
    const events: { t: number; kind: 'spike' | 'input' }[] = []
    const now = () => performance.now() / 1000
    handleRef.current = {
      spike: () => events.push({ t: now(), kind: 'spike' }),
      input: () => events.push({ t: now(), kind: 'input' }),
    }

    const style = getComputedStyle(canvas)
    let raf = 0
    const draw = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2)
      const w = canvas.clientWidth
      const h = canvas.clientHeight
      if (canvas.width !== Math.round(w * dpr)) {
        canvas.width = Math.round(w * dpr)
        canvas.height = Math.round(h * dpr)
      }
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
      ctx.clearRect(0, 0, w, h)
      const y = (v: number) => h - ((v - V_MIN) / (V_MAX - V_MIN)) * h

      // Graticule.
      ctx.strokeStyle = 'rgba(255,255,255,0.06)'
      ctx.lineWidth = 1
      ctx.beginPath()
      for (let i = 1; i < 6; i++) {
        const x = Math.round((i / 6) * w) + 0.5
        ctx.moveTo(x, 0)
        ctx.lineTo(x, h)
      }
      for (const v of [-80, -40, 0, 40]) {
        const yy = Math.round(y(v)) + 0.5
        ctx.moveTo(0, yy)
        ctx.lineTo(w, yy)
      }
      ctx.stroke()

      // Threshold.
      ctx.setLineDash([3, 4])
      ctx.strokeStyle = 'rgba(255,255,255,0.22)'
      ctx.beginPath()
      ctx.moveTo(0, Math.round(y(THRESH)) + 0.5)
      ctx.lineTo(w, Math.round(y(THRESH)) + 0.5)
      ctx.stroke()
      ctx.setLineDash([])

      // Trace.
      const t1 = now()
      while (events.length && t1 - events[0].t > WINDOW + 1) events.shift()
      const accent = style.getPropertyValue('--trace').trim() || '#86f2ff'
      ctx.strokeStyle = accent
      ctx.lineWidth = 1.4
      ctx.lineJoin = 'round'
      ctx.shadowColor = accent
      ctx.shadowBlur = 6
      ctx.beginPath()
      const steps = Math.ceil(w)
      for (let i = 0; i <= steps; i++) {
        const t = t1 - WINDOW + (i / steps) * WINDOW
        let v = REST + noise(t)
        for (const e of events) v += e.kind === 'spike' ? spikeDelta(t - e.t) : epspDelta(t - e.t)
        if (i === 0) ctx.moveTo(i, y(v))
        else ctx.lineTo((i / steps) * w, y(v))
      }
      ctx.stroke()
      ctx.shadowBlur = 0

      raf = requestAnimationFrame(draw)
    }
    raf = requestAnimationFrame(draw)
    return () => {
      cancelAnimationFrame(raf)
      handleRef.current = null
    }
  }, [handleRef, reducedMotion])

  return <canvas ref={canvasRef} className="trace-canvas" aria-hidden />
}

import { useCallback, useEffect, useRef, useState } from 'react'
import Grainient, { type GrainController } from './components/Grainient'
import NeuronCanvas, { type NeuronHandle } from './components/NeuronCanvas'
import MembraneTrace, { type TraceHandle } from './components/MembraneTrace'

const PRODUCT = 'Motus'

/** card.io's sweep: neutral grey field → stained, fluorescent field as the neuron fires. */
const GRAIN_GREY: [string, string, string] = ['#3d3d3d', '#2a2a2a', '#1c1c1c']
const GRAIN_LIVE: [string, string, string] = ['#0d6c86', '#142450', '#060a14']
const MAX_RIPPLES = 4

const channels = [
  { id: '01', name: 'Keystroke dynamics', detail: 'Dwell, flight and inter-key timing' },
  { id: '02', name: 'Speech acoustics', detail: 'Articulation rate, DDK, voice stability' },
  { id: '03', name: 'Handwriting kinematics', detail: 'Stroke velocity, pressure, tremor' },
]

const stains = [
  { label: 'Membrane', marker: 'GFP', color: '#86f2ff' },
  { label: 'Synaptic vesicles', marker: 'SYP', color: '#ff4fa3' },
  { label: 'Myelin', marker: 'MBP', color: '#aab4ff' },
  { label: 'Nucleus', marker: 'DAPI', color: '#5b78ff' },
]

function lerpHex(a: string, b: string, t: number) {
  const pa = [1, 3, 5].map((i) => parseInt(a.slice(i, i + 2), 16))
  const pb = [1, 3, 5].map((i) => parseInt(b.slice(i, i + 2), 16))
  return '#' + pa.map((v, i) => Math.round(v + (pb[i] - v) * t).toString(16).padStart(2, '0')).join('')
}

function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(() => window.matchMedia('(prefers-reduced-motion: reduce)').matches)
  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    const on = () => setReduced(mq.matches)
    mq.addEventListener('change', on)
    return () => mq.removeEventListener('change', on)
  }, [])
  return reduced
}

function useTyped(text: string, { speed = 120, delay = 300, skip = false } = {}) {
  const [n, setN] = useState(skip ? text.length : 0)
  useEffect(() => {
    if (skip) return
    let i = 0
    let timer = window.setTimeout(function tick() {
      i += 1
      setN(i)
      if (i < text.length) timer = window.setTimeout(tick, speed)
    }, delay)
    return () => window.clearTimeout(timer)
  }, [text, speed, delay, skip])
  return { shown: text.slice(0, n), done: n >= text.length }
}

function useClock() {
  const [s, setS] = useState(0)
  useEffect(() => {
    const start = performance.now()
    const id = window.setInterval(() => setS(Math.floor((performance.now() - start) / 1000)), 1000)
    return () => window.clearInterval(id)
  }, [])
  const pad = (v: number) => String(v).padStart(2, '0')
  return `${pad(Math.floor(s / 3600))}:${pad(Math.floor(s / 60) % 60)}:${pad(s % 60)}`
}

export default function App() {
  const reducedMotion = usePrefersReducedMotion()
  const rootRef = useRef<HTMLDivElement>(null)
  const grainRef = useRef<GrainController | null>(null)
  const neuronRef = useRef<NeuronHandle | null>(null)
  const traceRef = useRef<TraceHandle | null>(null)
  const target = useRef(reducedMotion ? 1 : 0)
  const progress = useRef(target.current)
  const lastSpike = useRef<number | null>(null)
  const rippleId = useRef(0)

  const [ripples, setRipples] = useState<{ id: number; x: number; y: number }[]>([])
  const [spikes, setSpikes] = useState(0)
  const [isi, setIsi] = useState<number | null>(null)
  const [stage, setStage] = useState({ x: 412.06, y: 188.3 })
  const { shown, done } = useTyped(PRODUCT, { skip: reducedMotion })
  const clock = useClock()

  // Smooth progress → background palette and UI tint (card.io's rAF lerp).
  useEffect(() => {
    let raf = 0
    let painted = -1
    const tick = () => {
      progress.current += (target.current - progress.current) * 0.03
      const p = progress.current
      if (Math.abs(p - painted) > 0.0005) {
        painted = p
        grainRef.current?.setColors(
          lerpHex(GRAIN_GREY[0], GRAIN_LIVE[0], p),
          lerpHex(GRAIN_GREY[1], GRAIN_LIVE[1], p),
          lerpHex(GRAIN_GREY[2], GRAIN_LIVE[2], p),
        )
        rootRef.current?.style.setProperty('--p', p.toFixed(4))
      }
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [])

  const onSpike = useCallback((x: number, y: number) => {
    target.current = Math.min(1, target.current + 0.1)
    traceRef.current?.spike()
    const t = performance.now()
    if (lastSpike.current !== null) setIsi((t - lastSpike.current) / 1000)
    lastSpike.current = t
    setSpikes((n) => n + 1)
    const id = ++rippleId.current
    setRipples((r) => [...r, { id, x, y }].slice(-MAX_RIPPLES))
    window.setTimeout(() => setRipples((r) => r.filter((v) => v.id !== id)), 3200)
  }, [])

  const onInput = useCallback(() => traceRef.current?.input(), [])

  return (
    <div
      ref={rootRef}
      className="app"
      onPointerMove={(e) => setStage({ x: 380 + (e.clientX / window.innerWidth) * 64, y: 160 + (e.clientY / window.innerHeight) * 48 })}
    >
      <div className="layer grain" aria-hidden>
        <Grainient colors={GRAIN_GREY} controllerRef={grainRef} paused={reducedMotion} />
      </div>

      <div className="layer ripples" aria-hidden>
        {ripples.map((r) => (
          <span key={r.id} className="ripple" style={{ left: `${r.x * 100}%`, top: `${r.y * 100}%` }} />
        ))}
      </div>

      <div className="layer stage">
        <NeuronCanvas
          progressRef={progress}
          handleRef={neuronRef}
          onSpike={onSpike}
          onInput={onInput}
          reducedMotion={reducedMotion}
        />
      </div>

      {/* Instrument chrome. */}
      <div className="layer hud" aria-hidden>
        <span className="reg reg-tl" />
        <span className="reg reg-tr" />
        <span className="reg reg-bl" />
        <span className="reg reg-br" />
      </div>

      <header className="topbar">
        <a className="brand" href="/" aria-label={`${PRODUCT} home`}>
          <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden>
            <circle cx="9" cy="10" r="3.6" fill="none" stroke="currentColor" strokeWidth="1.6" />
            <path d="M11.8 12.4 19 19.5M6.3 7.3 3.5 4.5M6.6 12.6 3 15.6M9.3 6.4 10 2.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" />
            <circle cx="19.4" cy="19.8" r="1.6" className="brand-bouton" />
          </svg>
          {PRODUCT}
        </a>
        <p className="meta">
          <span>Specimen 04</span>
          <span className="sep">/</span>
          <span>α-motor neuron · ventral horn</span>
          <span className="sep hide-sm">/</span>
          <span className="hide-sm">λ 405 · 488 · 561 nm</span>
        </p>
        <p className="rec">
          <span className="rec-dot" aria-hidden />
          REC <span className="num">{clock}</span>
        </p>
      </header>

      <aside className="scope" aria-label="Simulated membrane potential">
        <div className="scope-head">
          <span>V<sub>m</sub> · whole-cell</span>
          <span className="num">+48 / −92 mV</span>
        </div>
        <MembraneTrace handleRef={traceRef} reducedMotion={reducedMotion} />
        <div className="scope-foot">
          <span>
            spikes <b className="num">{String(spikes).padStart(3, '0')}</b>
          </span>
          <span>
            ISI <b className="num">{isi === null ? '—' : `${isi.toFixed(2)} s`}</b>
          </span>
          <button type="button" className="stim" onClick={() => neuronRef.current?.fire()}>
            Stimulate
          </button>
        </div>
      </aside>

      <main className="hero">
        <p className="eyebrow">ALS · longitudinal motor-function monitoring</p>
        <h1 className="title" aria-label={PRODUCT}>
          <span aria-hidden>{shown}</span>
          <span className={`cursor${done ? ' cursor-blink' : ''}`} aria-hidden>
            |
          </span>
        </h1>
        <div className={`reveal${done ? ' in' : ''}`}>
          <p className="lede">
            Passive, at-home measurement of how you type, speak and write. {PRODUCT} turns months of everyday motor
            data into a longitudinal record that helps neurologists recognise ALS sooner and follow its progression
            between clinic visits.
          </p>
          <ul className="channels">
            {channels.map((c) => (
              <li key={c.id}>
                <span className="ch num">CH {c.id}</span>
                <span className="ch-name">{c.name}</span>
                <span className="ch-detail">{c.detail}</span>
              </li>
            ))}
          </ul>
          <div className="ctas">
            <a className="btn btn-primary" href="#start">
              Start a baseline assessment
              <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden>
                <path d="M3 8h9M8.5 4.5 12 8l-3.5 3.5" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </a>
            <a className="btn btn-ghost" href="#clinicians">
              For clinicians
            </a>
          </div>
          <p className="disclaimer">Research prototype. Not a diagnostic device — built to augment clinical judgement, not replace it.</p>
        </div>
      </main>

      <footer className="legend" aria-label="Fluorescence channels">
        <ul>
          {stains.map((s) => (
            <li key={s.marker} style={{ '--stain': s.color } as React.CSSProperties}>
              <span className="swatch" aria-hidden />
              {s.label} <span className="marker">{s.marker}</span>
            </li>
          ))}
        </ul>
        <div className="scalebar" aria-hidden>
          <span className="bar" />
          <span className="num">20 µm</span>
        </div>
        <p className="coords num" aria-hidden>
          X {stage.x.toFixed(2)} · Y {stage.y.toFixed(2)} · Z 14.20 µm
        </p>
      </footer>

      <p className="hint" aria-hidden>
        Click the soma to stimulate
      </p>
    </div>
  )
}

