cat > src/index.css <<'EOF'
@import "tailwindcss";

/*
 * Visual language follows card.io's landing page (grain-shader field, typed
 * gradient title bottom-left, interactive 3D organ, ripples, grey → colour as
 * it comes alive), dressed as a fluorescence-microscopy instrument.
 */

@theme {
  --font-heading: "Sora", ui-sans-serif, system-ui, sans-serif;
  --font-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "JetBrains Mono Variable", ui-monospace, monospace;
}

:root {
  color-scheme: dark;
  --p: 0; /* 0 = unstained grey, 1 = fluorescent; driven from App */
  --ink: #f4f7fa;
  --muted: rgb(226 232 240 / 0.64);
  --faint: rgb(226 232 240 / 0.42);
  --line: rgb(255 255 255 / 0.12);
  --accent: color-mix(in oklab, #86f2ff calc(var(--p) * 100%), #a3abb8);
  --synapse: color-mix(in oklab, #ff4fa3 calc(var(--p) * 100%), #b9bec8);
  --trace: #86f2ff;
  --gutter: max(32px, 4vw);
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
}

* { box-sizing: border-box; }

html, body, #root { height: 100%; }

body {
  margin: 0;
  overflow: hidden;
  background: #0a0d14;
  color: var(--ink);
  font-family: var(--font-body);
  -webkit-font-smoothing: antialiased;
}

.num { font-variant-numeric: tabular-nums; font-family: var(--font-mono); }

/* ---------- layer stack ---------- */

.app {
  position: relative;
  height: 100dvh;
  width: 100%;
  overflow: hidden;
  isolation: isolate;
}

.layer { position: absolute; inset: 0; }
.grain { z-index: 0; pointer-events: none; }
.ripples { z-index: 1; pointer-events: none; overflow: hidden; }
.stage { z-index: 2; }
.hud { z-index: 3; pointer-events: none; }

.topbar, .scope, .hero, .legend, .hint { z-index: 4; position: absolute; }

/* Vignette: keeps the corners readable over the shader. */
.hud::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(120% 90% at 70% 35%, transparent 40%, rgb(4 6 12 / 0.55) 100%),
    linear-gradient(to top, rgb(4 6 12 / 0.55), transparent 45%);
}

.reg { position: absolute; width: 18px; height: 18px; border-color: rgb(255 255 255 / 0.28); border-style: solid; border-width: 0; }
.reg-tl { top: 14px; left: 14px; border-top-width: 1px; border-left-width: 1px; }
.reg-tr { top: 14px; right: 14px; border-top-width: 1px; border-right-width: 1px; }
.reg-bl { bottom: 14px; left: 14px; border-bottom-width: 1px; border-left-width: 1px; }
.reg-br { bottom: 14px; right: 14px; border-bottom-width: 1px; border-right-width: 1px; }

/* ---------- top bar ---------- */

.topbar {
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 22px var(--gutter);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  pointer-events: none;
}

.topbar > * { pointer-events: auto; }

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--ink);
  text-decoration: none;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 15px;
  letter-spacing: 0.02em;
  text-transform: none;
}

.brand svg { color: var(--accent); }
.brand-bouton { fill: var(--synapse); }

.meta { margin: 0; display: flex; gap: 10px; flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; }
.meta .sep { color: var(--faint); }

.rec { margin: 0; display: inline-flex; align-items: center; gap: 8px; color: var(--ink); }
.rec-dot { width: 7px; height: 7px; border-radius: 50%; background: #ff4d5e; box-shadow: 0 0 10px #ff4d5e; animation: blink 1.4s steps(1, end) infinite; }

/* ---------- oscilloscope ---------- */

.scope {
  top: 72px;
  right: var(--gutter);
  width: 300px;
  padding: 12px 14px 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgb(5 8 16 / 0.42);
  backdrop-filter: blur(6px);
  font-family: var(--font-mono);
  font-size: 10.5px;
  letter-spacing: 0.06em;
  color: var(--muted);
  --trace: #86f2ff;
}

.scope-head, .scope-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.scope-head { text-transform: uppercase; letter-spacing: 0.12em; }
.scope-head sub { font-size: 0.8em; }
.scope-foot { margin-top: 8px; }
.scope-foot b { color: var(--ink); font-weight: 500; }

.trace-canvas {
  display: block;
  width: 100%;
  height: 92px;
  margin-top: 8px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  filter: saturate(var(--p));
}

.stim {
  appearance: none;
  border: 1px solid color-mix(in oklab, var(--accent) 55%, transparent);
  background: color-mix(in oklab, var(--accent) 10%, transparent);
  color: var(--ink);
  font: inherit;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 5px 9px;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 150ms ease-out, transform 120ms ease-out;
}
.stim:active { transform: scale(0.97); }
@media (hover: hover) { .stim:hover { background: color-mix(in oklab, var(--accent) 22%, transparent); } }

/* ---------- hero ---------- */

.hero {
  left: var(--gutter);
  bottom: max(9vh, 56px);
  width: min(600px, calc(100% - 2 * var(--gutter)));
  pointer-events: none;
}
.hero a, .hero button { pointer-events: auto; }

.eyebrow {
  margin: 0 0 14px;
  font-family: var(--font-mono);
  font-size: 11.5px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
}

.title {
  margin: 0 0 18px;
  min-height: 1em;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: clamp(3.5rem, 7.5vw, 6.5rem);
  line-height: 0.95;
  letter-spacing: -0.045em;
}
.title > span:first-child {
  background: linear-gradient(to right, #ffffff, #cbd5e1);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.cursor { margin-left: 0.04em; font-weight: 300; color: var(--accent); }
.cursor-blink { animation: blink 1.1s steps(1, end) infinite; }

.reveal > * { opacity: 0; transform: translateY(24px); transition: opacity 700ms var(--ease-out), transform 700ms var(--ease-out); }
.reveal.in > * { opacity: 1; transform: none; }
.reveal.in > :nth-child(2) { transition-delay: 80ms; }
.reveal.in > :nth-child(3) { transition-delay: 160ms; }
.reveal.in > :nth-child(4) { transition-delay: 240ms; }

.lede {
  margin: 0;
  max-width: 52ch;
  font-size: 16px;
  line-height: 1.6;
  color: var(--muted);
  text-wrap: pretty;
}

.channels {
  list-style: none;
  margin: 24px 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.channels li { display: flex; flex-direction: column; gap: 3px; padding-top: 10px; border-top: 1px solid var(--line); }
.ch { font-size: 10.5px; letter-spacing: 0.14em; color: var(--accent); }
.ch-name { font-size: 14px; font-weight: 500; color: var(--ink); }
.ch-detail { font-size: 12.5px; line-height: 1.4; color: var(--faint); }

.ctas { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 28px; }

.btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 46px;
  padding: 12px 22px;
  border-radius: 8px;
  font-size: 15px;
  font-weight: 500;
  text-decoration: none;
  transition: transform 200ms var(--ease-out), box-shadow 200ms var(--ease-out), background-color 200ms ease-out, border-color 200ms ease-out;
}
.btn:active { transform: translateY(1px); }
.btn:focus-visible, .stim:focus-visible, .brand:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

.btn-primary { background: #fff; color: #0b1220; box-shadow: 0 2px 8px rgb(0 0 0 / 0.18); }
.btn-ghost { color: var(--ink); border: 1px solid rgb(255 255 255 / 0.24); background: rgb(255 255 255 / 0.03); }

@media (hover: hover) {
  .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgb(0 0 0 / 0.25), 0 0 0 4px color-mix(in oklab, var(--accent) 22%, transparent); }
  .btn-ghost:hover { border-color: color-mix(in oklab, var(--accent) 70%, transparent); background: color-mix(in oklab, var(--accent) 8%, transparent); }
}

.disclaimer { margin: 18px 0 0; font-size: 12px; color: var(--faint); }

/* ---------- legend / scale bar ---------- */

.legend {
  right: var(--gutter);
  bottom: 30px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
  font-family: var(--font-mono);
  font-size: 10.5px;
  letter-spacing: 0.08em;
  color: var(--muted);
  pointer-events: none;
}
.legend ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; align-items: flex-end; gap: 6px; }
.legend li { display: inline-flex; align-items: center; gap: 8px; }
.swatch {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: color-mix(in oklab, var(--stain) calc(var(--p) * 100%), #9aa1ad);
  box-shadow: 0 0 calc(var(--p) * 10px) var(--stain);
}
.marker { color: var(--faint); }
.scalebar { display: inline-flex; align-items: center; gap: 10px; color: var(--ink); }
.scalebar .bar { width: 72px; height: 3px; background: var(--ink); border-radius: 1px; }
.coords { margin: 0; color: var(--faint); font-size: 10px; }

.hint {
  top: 74px;
  left: 50%;
  transform: translateX(-50%);
  margin: 0;
  font-family: var(--font-mono);
  font-size: 10.5px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--faint);
  pointer-events: none;
}

/* ---------- ripple (card.io) ---------- */

.ripple {
  position: absolute;
  width: 200vmax;
  height: 200vmax;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    transparent 0%,
    transparent 40%,
    color-mix(in oklab, var(--accent) 7%, transparent) 55%,
    color-mix(in oklab, var(--accent) 11%, transparent) 65%,
    color-mix(in oklab, var(--accent) 6%, transparent) 75%,
    transparent 90%
  );
  transform: translate(-50%, -50%) scale(0);
  animation: ripple 3s cubic-bezier(0.2, 0.6, 0.35, 1) forwards;
}

@keyframes ripple {
  from { transform: translate(-50%, -50%) scale(0); opacity: 1; }
  to { transform: translate(-50%, -50%) scale(1); opacity: 0; }
}

@keyframes blink { 50% { opacity: 0; } }

/* ---------- responsive ---------- */

@media (max-width: 1100px) {
  .hint, .meta .hide-sm { display: none; }
}

@media (max-width: 860px) {
  .scope { display: none; }
  .legend ul, .coords { display: none; }
  .channels { grid-template-columns: 1fr; gap: 10px; }
  .channels li { flex-direction: row; align-items: baseline; gap: 10px; }
  .ch-detail { display: none; }
  .meta { display: none; }
  .topbar { justify-content: space-between; }
  .hero { bottom: 32px; }
  .lede { font-size: 15px; }
}

@media (max-height: 760px) and (min-width: 861px) {
  .channels { display: none; }
  .title { font-size: clamp(3rem, 6vw, 5rem); }
}

@media (prefers-reduced-motion: reduce) {
  .reveal > *, .btn, .stim { transition: none; }
  .rec-dot, .cursor-blink { animation: none; }
  .ripple { display: none; }
}
