}

/* ---------- ripple (card.io) ---------- */

.ripple {
  position: absolute;
  width: 200vmax;
  height: 200vmax;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    transparent 0%,
    transparent 40%,
    color-mix(in oklab, var(--accent) 7%, transparent) 55%,
    color-mix(in oklab, var(--accent) 11%, transparent) 65%,
    color-mix(in oklab, var(--accent) 6%, transparent) 75%,
    transparent 90%
  );
  transform: translate(-50%, -50%) scale(0);
  animation: ripple 3s cubic-bezier(0.2, 0.6, 0.35, 1) forwards;
}

@keyframes ripple {
  from { transform: translate(-50%, -50%) scale(0); opacity: 1; }
  to { transform: translate(-50%, -50%) scale(1); opacity: 0; }
}

@keyframes blink { 50% { opacity: 0; } }

/* ---------- responsive ---------- */

@media (max-width: 1100px) {
  .hint, .meta .hide-sm { display: none; }
}

@media (max-width: 860px) {
  .scope { display: none; }
  .legend ul, .coords { display: none; }
  .channels { grid-template-columns: 1fr; gap: 10px; }
  .channels li { flex-direction: row; align-items: baseline; gap: 10px; }
  .ch-detail { display: none; }
  .meta { display: none; }
  .topbar { justify-content: space-between; }
  .hero { bottom: 32px; }
  .lede { font-size: 15px; }
}

@media (max-height: 760px) and (min-width: 861px) {
  .channels { display: none; }
  .title { font-size: clamp(3rem, 6vw, 5rem); }
}

@media (prefers-reduced-motion: reduce) {
  .reveal > *, .btn, .stim { transition: none; }
  .rec-dot, .cursor-blink { animation: none; }
  .ripple { display: none; }
}

