// Real-time screenshots via Chrome DevTools Protocol.
// usage: node cdp-shot.mjs <url> <outPrefix> <width> <height> <steps as "waitMs:js|waitMs|...">
import { spawn } from 'node:child_process'
import { writeFileSync, mkdtempSync } from 'node:fs'
import { join } from 'node:path'
import { tmpdir } from 'node:os'

const [url, out, w = '1440', h = '900', plan = '6000'] = process.argv.slice(2)
const port = 9333
const prof = mkdtempSync(join(tmpdir(), 'cdp-'))
const chrome = spawn('C:/Program Files/Google/Chrome/Application/chrome.exe', [
  '--headless=new', `--remote-debugging-port=${port}`, `--window-size=${w},${h}`,
  '--use-angle=swiftshader', '--enable-unsafe-swiftshader', `--user-data-dir=${prof}`, 'about:blank',
], { stdio: 'ignore' })
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
let targets
for (let i = 0; i < 40; i++) {
  try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); break } catch { await sleep(250) }
}
const page = targets.find((t) => t.type === 'page')
const ws = new WebSocket(page.webSocketDebuggerUrl)
await new Promise((r) => ws.addEventListener('open', r))
let id = 0
const pending = new Map()
ws.addEventListener('message', (e) => {
  const m = JSON.parse(e.data)
  if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id) }
  if (m.method === 'Runtime.exceptionThrown') console.log('EXC', JSON.stringify(m.params.exceptionDetails).slice(0, 400))
  if (m.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(m.params.type)) console.log('CONSOLE', m.params.type, m.params.args.map((a) => a.value ?? a.description).join(' ').slice(0, 300))
})
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })) })
await send('Runtime.enable')
await send('Page.enable')
await send('Emulation.setDeviceMetricsOverride', { width: +w, height: +h, deviceScaleFactor: 1, mobile: false })
await send('Page.navigate', { url })
let n = 0
for (const step of plan.split('|')) {
  const [ms, ...js] = step.split(':')
  await sleep(+ms)
  if (js.length) await send('Runtime.evaluate', { expression: js.join(':') })
  else {
    const r = await send('Page.captureScreenshot', { format: 'png' })
    const f = `${out}-${++n}.png`
    writeFileSync(f, Buffer.from(r.result.data, 'base64'))
    console.log('wrote', f)
  }
}
ws.close()
chrome.kill()
process.exit(0)

