export function GoogleSignInButton({ authError = false, onUserChange }: {
  authError?: boolean;
  onUserChange?: (user: User | null) => void;
}) {
  const [user, setUser] = useState<User | null>(null);
  const [ready, setReady] = useState(false);
  const [busy, setBusy] = useState(false);
  const [failedAvatar, setFailedAvatar] = useState<string | null>(null);
  const [error, setError] = useState(
    authError ? "Sign-in was not completed. Please try again." : "",
  );
  const [profileOpen, setProfileOpen] = useState(false);
  const profileActionsId = useId();
  const configured = Boolean(
    process.env.NEXT_PUBLIC_SUPABASE_URL &&
      process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
  );
  const name = [user?.user_metadata?.full_name, user?.user_metadata?.name, user?.email]
    .find((value): value is string => typeof value === "string" && value.trim().length > 0) ?? "Your profile";
  const avatar = [user?.user_metadata?.avatar_url, user?.user_metadata?.picture]
    .find((value): value is string => typeof value === "string" && /^https:\/\//i.test(value));

  useEffect(() => {
    if (!configured) return;
    const supabase = createClient();
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
      onUserChange?.(session?.user ?? null);
      setReady(true);
    });
    return () => subscription.unsubscribe();
  }, [configured, onUserChange]);

  async function handleClick() {
    setBusy(true);
    setError("");

    try {
      const supabase = createClient();

      if (user) {
        const { error } = await supabase.auth.signOut({ scope: "local" });
        if (error) throw error;
        setBusy(false);
