          <path fill="#34A853" d="M24 44c5.51 0 10.13-1.83 13.51-4.96l-6.61-5.14c-1.83 1.23-4.17 1.97-6.9 1.97-5.32 0-9.84-3.59-11.46-8.43H5.72v5.3A20 20 0 0 0 24 44Z" />
          <path fill="#FBBC05" d="M12.54 27.44a12 12 0 0 1 0-6.88v-5.3H5.72a20 20 0 0 0 0 17.48l6.82-5.3Z" />
          <path fill="#EA4335" d="M24 12.13c3.01 0 5.69 1.03 7.82 3.05l5.86-5.86A19.6 19.6 0 0 0 24 4 20 20 0 0 0 5.72 15.26l6.82 5.3C14.16 15.72 18.68 12.13 24 12.13Z" />
        </svg>
      ) : null}
      {busy ? (user ? "Signing out…" : "Connecting…") : user ? "Sign out" : "Sign in with Google"}
    </button>
  );

  return (
    <div className="grid min-w-0 grid-cols-1 gap-3 text-sm">
      {user ? (
        <div className="surface w-full p-2 shadow-xl">
          <button type="button" className="button w-full !justify-start !gap-2 !bg-transparent !p-0 !text-left !text-foreground"
            aria-label="Profile menu" aria-expanded={profileOpen} aria-controls={profileActionsId}
            onClick={() => setProfileOpen(open => !open)}>
            <span className="relative flex size-8 shrink-0 items-center justify-center overflow-hidden rounded-full border border-border bg-background text-sm text-accent" aria-hidden="true">
              {name.charAt(0).toUpperCase()}
              {avatar && avatar !== failedAvatar ? (
                // Provider avatars are already thumbnails and have user-specific hosts.
                // eslint-disable-next-line @next/next/no-img-element
                <img key={avatar} src={avatar} alt="" width={48} height={48} referrerPolicy="no-referrer" onError={() => setFailedAvatar(avatar)} className="absolute inset-0 size-full object-cover" />
              ) : null}
            </span>
            <span className="min-w-0 flex-1">
              <span className="block truncate text-sm font-semibold">{name}</span>
              <span className="block truncate text-muted">{user.email ?? "Google account"}</span>
            </span>
            <span aria-hidden="true" className={`text-accent transition-transform duration-300 motion-reduce:transition-none ${profileOpen ? "rotate-180" : ""}`}>⌃</span>
          </button>
          <div id={profileActionsId} aria-hidden={!profileOpen} inert={!profileOpen}
            className={`grid transition-[grid-template-rows,opacity] duration-300 ease-out motion-reduce:transition-none ${profileOpen ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0"}`}>
            <div className="min-h-0 overflow-hidden">
              <div className="mt-4 border-t border-border pt-4">{authButton}</div>
