"use client";

import { useEffect, useState } from "react";
import { createClient } from "@/lib/supabase/client";
import { dashboardColumns, parseDashboardRows, summarizeDashboard, type DashboardDay } from "@/lib/dashboard";
import "./overview-dashboard.css";

const number = (value: number) => new Intl.NumberFormat("en-US").format(value);
const compact = (value: number) => new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 }).format(value);
const money = (cents: number) => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(cents / 100);
const date = (day: string) => new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" }).format(new Date(day));
const colors = ["var(--color-accent)", "var(--color-foreground)", "var(--color-muted)", "var(--color-border)"];

function Trend({ series, label, mini = false }: { series: number[][]; label: string; mini?: boolean }) {
  const max = Math.max(1, ...series.flat());
  return <svg className={mini ? "dashboard-spark" : "dashboard-trend"} viewBox="0 0 480 120" preserveAspectRatio="none" role="img" aria-label={label}>
    {!mini && [12, 42, 72, 102].map(y => <line key={y} x1="0" x2="480" y1={y} y2={y} stroke="currentColor" opacity=".12" strokeDasharray="3 6" />)}
    {series.map((values, index) => {
      const points = values.map((value, i) => `${i * 480 / Math.max(1, values.length - 1)},${112 - value / max * 100}`).join(" ");
      return <g key={index} style={{ color: colors[index % colors.length] }}>
        {!mini && <polygon points={`0,120 ${points} 480,120`} fill="currentColor" opacity=".06" />}
        <polyline points={points} fill="none" stroke="currentColor" strokeWidth={mini ? 2 : 2.5} vectorEffect="non-scaling-stroke" strokeLinejoin="round" strokeLinecap="round" />
      </g>;
    })}
  </svg>;
}

function Metric({ label, value, detail, values }: { label: string; value: string; detail: string; values: number[] }) {
  return <section className="surface dashboard-card dashboard-metric">
    <h2>{label}</h2><strong className="dashboard-value">{value}</strong>
    <div className="dashboard-metric-bottom"><span>{detail}</span><Trend series={[values]} label={`${label} daily trend`} mini /></div>
  </section>;
}

export default function OverviewDashboard({ userId }: { userId: string }) {
  const [rows, setRows] = useState<DashboardDay[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [attempt, setAttempt] = useState(0);
  const [days, setDays] = useState(28);

  useEffect(() => {
    const controller = new AbortController();
    async function load() {
      setLoading(true); setError(""); setRows([]);
      try {
        if (!userId) throw new Error("Sign in to view your dashboard.");
        const { data, error } = await createClient().from("dashboard_daily")
          .select(dashboardColumns).eq("user_id", userId).order("day", { ascending: false })
          .limit(28).abortSignal(controller.signal);
        if (error) throw new Error("Dashboard data is unavailable.");
        if (!controller.signal.aborted) setRows(parseDashboardRows(data));
      } catch (error) {
        if (!controller.signal.aborted) setError(error instanceof Error ? error.message : "Could not load dashboard.");
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    }
    void load();
    return () => controller.abort();
  }, [userId, attempt]);

  const data = summarizeDashboard(rows, days);
  const { period, latest } = data;
  const first = period[0];
  const maxExperiments = Math.max(1, ...period.map(row => row.completed + row.failed));
  const active = (latest?.running ?? 0) + (latest?.queued ?? 0);
  const barScale = Math.max(1, ...data.tools.map(([, value]) => value));
  const series = (key: "running" | "agent_runs" | "api_calls" | "tool_calls" | "latency_ms" | "spend_cents") => period.map(row => row[key]);

  return <div className="overview-dashboard">
    <header className="dashboard-heading">
      <div><p className="eyebrow">Workspace / Overview</p><h1>Welcome back.</h1></div>
      <div className="dashboard-controls">
        <div className="dashboard-range" role="group" aria-label="Dashboard time range">
          {[7, 14, 28].map(range => <button type="button" className="button" key={range} aria-pressed={days === range} onClick={() => setDays(range)}>{range}d</button>)}
        </div>
      </div>
    </header>
    {loading ? <div className="surface dashboard-state" role="status">Loading your workspace…</div>
      : error ? <div className="surface dashboard-state" role="alert"><p>{error}</p><button type="button" className="button" onClick={() => setAttempt(value => value + 1)}>Retry</button></div>
      : !latest || !first ? <div className="surface dashboard-state"><h2>No analytics yet.</h2><p>There’s no dashboard data for this account.</p></div>
      : <>
        <div className="dashboard-period"><span>{date(first.day)} — {date(latest.day)}</span><span>{period.length} daily snapshots</span></div>
        <div className="dashboard-grid" aria-live="polite">
          <Metric label="Experiments running" value={number(latest.running)} detail={`${latest.queued} queued · latest snapshot`} values={series("running")} />
          <Metric label="Agent runs" value={number(data.agentRuns)} detail={`${data.agents.length} agent roles`} values={series("agent_runs")} />
          <Metric label="API calls" value={number(data.calls)} detail={`${compact(data.calls / period.length)} / day`} values={series("api_calls")} />
          <Metric label="Tool invocations" value={number(data.toolCalls)} detail={`${data.tools.length} tools used`} values={series("tool_calls")} />

          <section className="surface dashboard-card dashboard-wide">
            <div className="dashboard-card-head"><h2>Experiment throughput</h2><span className="dashboard-tag">{data.success === null ? "—" : `${data.success.toFixed(1)}%`} success</span></div>
            <div className="dashboard-chart-total"><strong>{number(data.completed)}</strong><span>completed <span className="dashboard-failed">/ {data.failed} failed</span></span></div>
            <div className="dashboard-bars" role="img" aria-label={`${data.completed} completed and ${data.failed} failed experiments from ${date(first.day)} to ${date(latest.day)}. Daily values are in the data table below.`}>
              {period.map(row => <div className="dashboard-bar-track" key={row.day} title={`${date(row.day)}: ${row.completed} completed, ${row.failed} failed`}>
                <div className="dashboard-bar" style={{ height: `${(row.completed + row.failed) / maxExperiments * 100}%` }}>
                  {row.failed > 0 && <span className="dashboard-bar-failed" style={{ flexGrow: row.failed }} />}
                  <span style={{ flexGrow: row.completed }} />
                </div>
              </div>)}
            </div>
            <div className="dashboard-axis"><span>{date(first.day)}</span><span>{date(period[Math.floor(period.length / 2)].day)}</span><span>{date(latest.day)}</span></div>
            <div className="dashboard-card-footer"><span><i /> Completed</span><span><i className="dashboard-failed-dot" /> Failed</span><span className="dashboard-push">{number(data.started)} started</span></div>
          </section>

          <section className="surface dashboard-card dashboard-third">
            <div className="dashboard-card-head"><h2>Workload</h2><span className="dashboard-tiny">{date(latest.day)}</span></div>
            <div className="dashboard-donut-wrap"><div className="dashboard-donut" style={{ background: `conic-gradient(var(--color-accent) 0 ${active ? latest.running / active * 100 : 0}%, var(--color-border) 0 100%)` }} role="img" aria-label={`${latest.running} running, ${latest.queued} queued`}><div><strong>{active}</strong><span>in flight</span></div></div></div>
            <div className="dashboard-workload-row"><span><i /> Running</span><strong>{latest.running}</strong></div>
            <div className="dashboard-workload-row"><span><i className="dashboard-queued-dot" /> Queued</span><strong>{latest.queued}</strong></div>
            <div className="dashboard-card-footer"><span>{latest.completed} completed in latest day</span></div>
          </section>

          <section className="surface dashboard-card dashboard-wide">
            <div className="dashboard-card-head"><h2>Request volume</h2><span className="dashboard-tiny">calls / day</span></div>
            <div className="dashboard-inline-stats"><div><strong>{compact(data.calls)}</strong><span><i /> API calls</span></div><div><strong>{compact(data.toolCalls)}</strong><span><i className="dashboard-light-dot" /> Tool calls</span></div></div>
            <Trend series={[series("api_calls"), series("tool_calls")]} label="Daily API and tool call volume; exact values in the daily data table" />
            <div className="dashboard-axis"><span>{date(first.day)}</span><span>{date(latest.day)}</span></div>
          </section>

          <section className="surface dashboard-card dashboard-third">
            <div className="dashboard-card-head"><h2>Tools used</h2><span className="dashboard-tiny">{number(data.toolCalls)} calls</span></div>
            <div className="dashboard-rank-list">{data.tools.map(([name, value], i) => <div key={name} className="dashboard-rank">
              <div><span><small>{String(i + 1).padStart(2, "0")}</small>{name}</span><strong>{number(value)}</strong></div>
              <div className="dashboard-meter"><span style={{ width: `${value / barScale * 100}%` }} /></div>
            </div>)}</div>
          </section>

          <section className="surface dashboard-card dashboard-third">
            <div className="dashboard-card-head"><h2>Agent mix</h2><span className="dashboard-tiny">runs</span></div>
            <div className="dashboard-stack" role="img" aria-label={data.agents.map(([name, n]) => `${name}: ${n}`).join(", ")}>
              {data.agents.map(([name, value], i) => <span key={name} style={{ flexGrow: value, background: colors[i % colors.length] }} title={`${name}: ${number(value)}`} />)}
            </div>
            <div className="dashboard-agent-list">{data.agents.map(([name, value], i) => <div key={name}><span><i style={{ background: colors[i % colors.length] }} />{name}</span><span>{data.agentRuns ? (value / data.agentRuns * 100).toFixed(0) : 0}%</span><strong>{number(value)}</strong></div>)}</div>
          </section>

          <section className="surface dashboard-card dashboard-third">
            <div className="dashboard-card-head"><h2>Response latency</h2><span className="dashboard-tiny">weighted mean</span></div>
            <div className="dashboard-chart-total"><strong>{data.latency === null ? "—" : (data.latency / 1000).toFixed(2)}</strong><span>seconds</span></div>
            <Trend series={[series("latency_ms")]} label="Daily mean response latency; exact values in the daily data table" />
            <div className="dashboard-axis"><span>{date(first.day)}</span><span>{date(latest.day)}</span></div>
            <div className="dashboard-card-footer"><span>Latest day</span><strong className="dashboard-push">{(latest.latency_ms / 1000).toFixed(2)} s</strong></div>
          </section>

          <section className="surface dashboard-card dashboard-third">
            <div className="dashboard-card-head"><h2>Model spend</h2><span className="dashboard-tiny">USD</span></div>
            <div className="dashboard-chart-total"><strong>{money(data.spendCents)}</strong></div>
            <Trend series={[series("spend_cents")]} label="Daily model spend; exact values in the daily data table" />
            <div className="dashboard-axis"><span>{date(first.day)}</span><span>{date(latest.day)}</span></div>
            <div className="dashboard-card-footer"><span>{compact(data.tokens)} tokens</span><span className="dashboard-push">{data.agentRuns ? money(data.spendCents / data.agentRuns) : "—"} / run</span></div>
          </section>
        </div>
        <details className="dashboard-data"><summary>Daily data <span>{period.length} rows</span></summary><div className="dashboard-table-scroll" tabIndex={0} role="region" aria-label="Daily dashboard values"><table><caption className="sr-only">Daily workspace analytics</caption><thead><tr>{["Date", "Completed", "Failed", "Agents", "API calls", "Tool calls", "Latency", "Spend"].map(label => <th key={label} scope="col">{label}</th>)}</tr></thead><tbody>{[...period].reverse().map(row => <tr key={row.day}><th scope="row">{date(row.day)}</th><td>{row.completed}</td><td>{row.failed}</td><td>{row.agent_runs}</td><td>{number(row.api_calls)}</td><td>{number(row.tool_calls)}</td><td>{(row.latency_ms / 1000).toFixed(2)} s</td><td>{money(row.spend_cents)}</td></tr>)}</tbody></table></div></details>
      </>}
  </div>;
}
.overview-dashboard { max-width: 1440px; margin-inline: auto; font-size: .875rem; font-weight: 400; font-variant-numeric: tabular-nums; }
.dashboard-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 1.5rem; margin-bottom: 1.5rem; }
.dashboard-heading h1 { margin-top: .75rem; font-size: clamp(2.75rem, 4vw, 4rem); }
.dashboard-heading .eyebrow { font-size: .625rem; }
.dashboard-controls { display: flex; align-items: center; flex-wrap: wrap; gap: .75rem; }
.dashboard-range { display: flex; padding: .25rem; border: 1px solid var(--color-border); border-radius: var(--radius-control); background: var(--color-background); }
.dashboard-range .button { min-height: 2rem; padding: .25rem .75rem; background: transparent; color: var(--color-muted); border-radius: .25rem; font-size: .75rem; }
.dashboard-range .button[aria-pressed="true"] { background: var(--color-foreground); color: var(--color-background); }
.dashboard-range .button:hover:not([aria-pressed="true"]) { background: var(--color-surface); color: var(--color-foreground); }
.dashboard-period { display: flex; justify-content: space-between; gap: .75rem; color: var(--color-muted); font-size: .6875rem; margin-bottom: .75rem; }
.dashboard-grid { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); gap: .75rem; }
.dashboard-card { min-width: 0; padding: 1.25rem; border-color: color-mix(in srgb, var(--color-border) 65%, transparent); border-radius: .75rem; overflow: hidden; }
.dashboard-card h2 { font-size: 1.125rem; }
.dashboard-metric { grid-column: span 3; }
.dashboard-metric h2 { font-size: .9375rem; color: var(--color-muted); }
.dashboard-value { display: block; font-size: clamp(1.875rem, 2.8vw, 2.75rem); line-height: 1.2; font-weight: 400; letter-spacing: -.04em; margin-top: .75rem; }
.dashboard-metric-bottom { display: flex; align-items: flex-end; justify-content: space-between; gap: .5rem; margin-top: .75rem; }
.dashboard-metric-bottom > span { color: var(--color-muted); font-size: .6875rem; }
.dashboard-spark { flex: none; width: 35%; height: 1.75rem; }
.dashboard-wide { grid-column: span 8; }
.dashboard-third { grid-column: span 4; }
.dashboard-card-head { display: flex; align-items: center; justify-content: space-between; gap: .75rem; min-height: 1.5rem; }
.dashboard-tag { flex: none; color: var(--color-accent); background: color-mix(in srgb, var(--color-accent) 8%, transparent); border: 1px solid color-mix(in srgb, var(--color-accent) 25%, transparent); border-radius: .25rem; font-size: .6875rem; padding: .125rem .375rem; }
.dashboard-tiny { font-size: .625rem; color: var(--color-muted); text-align: right; }
.dashboard-chart-total { display: flex; align-items: baseline; gap: .75rem; margin: .75rem 0 1rem; }
.dashboard-chart-total > strong { font-size: 2.25rem; line-height: 1.2; font-weight: 400; letter-spacing: -.04em; }
.dashboard-chart-total > span { font-size: .75rem; color: var(--color-muted); }
.dashboard-failed { color: var(--color-muted); margin-left: .375rem; }
.dashboard-bars { display: flex; align-items: flex-end; gap: clamp(3px, .65vw, 8px); height: 8.5rem; border-bottom: 1px solid var(--color-border); background: repeating-linear-gradient(to top, transparent 0, transparent calc(25% - 1px), color-mix(in srgb, var(--color-border) 20%, transparent) calc(25% - 1px), color-mix(in srgb, var(--color-border) 20%, transparent) 25%); }
.dashboard-bar-track { height: 100%; min-width: 0; flex: 1; display: flex; align-items: flex-end; }
.dashboard-bar { width: 100%; min-height: 0; display: flex; flex-direction: column; overflow: hidden; border-radius: 3px 3px 0 0; background: var(--color-accent); opacity: .8; transition: opacity 150ms; }
.dashboard-bar-track:hover .dashboard-bar { opacity: 1; }
.dashboard-bar-failed { background: var(--color-danger); min-height: 3px; }
.dashboard-axis { display: flex; justify-content: space-between; font-size: .625rem; color: var(--color-muted); margin-top: .5rem; }
.dashboard-card-footer { display: flex; align-items: center; flex-wrap: wrap; gap: .75rem; font-size: .6875rem; color: var(--color-muted); margin-top: 1rem; padding-top: .75rem; border-top: 1px solid color-mix(in srgb, var(--color-border) 40%, transparent); }
.dashboard-card-footer span, .dashboard-workload-row span, .dashboard-inline-stats span, .dashboard-agent-list > div > span:first-child { display: inline-flex; align-items: center; gap: .375rem; }
.overview-dashboard i { display: inline-block; flex: none; width: .375rem; height: .375rem; border-radius: 50%; background: var(--color-accent); }
.overview-dashboard .dashboard-failed-dot { background: var(--color-danger); }
.overview-dashboard .dashboard-queued-dot { background: var(--color-border); }
.overview-dashboard .dashboard-light-dot { background: var(--color-foreground); }
.dashboard-push { margin-left: auto; }
.dashboard-donut-wrap { display: flex; justify-content: center; margin: 1.25rem 0; }
.dashboard-donut { display: grid; place-items: center; width: 9rem; height: 9rem; border-radius: 50%; transform: rotate(-90deg); }
.dashboard-donut > div { display: flex; flex-direction: column; align-items: center; justify-content: center; width: 7.75rem; height: 7.75rem; border-radius: 50%; background: var(--color-surface); transform: rotate(90deg); }
.dashboard-donut strong { font-size: 2.75rem; font-weight: 400; line-height: 1.15; }
.dashboard-donut span { font-size: .6875rem; color: var(--color-muted); }
.dashboard-workload-row { display: flex; justify-content: space-between; align-items: center; margin-top: .375rem; font-size: .75rem; }
.dashboard-workload-row strong { font-weight: 400; }
.dashboard-inline-stats { display: flex; gap: 2rem; margin: 1rem 0 1.25rem; }
.dashboard-inline-stats > div { display: flex; flex-direction: column; gap: .25rem; }
.dashboard-inline-stats strong { font-size: 2rem; font-weight: 400; line-height: 1.2; letter-spacing: -.03em; }
.dashboard-inline-stats span { font-size: .6875rem; color: var(--color-muted); }
.dashboard-trend { width: 100%; height: 6.5rem; overflow: visible; }
.dashboard-wide .dashboard-trend { height: 8rem; }
.dashboard-rank-list { display: flex; flex-direction: column; gap: .875rem; margin-top: 1.25rem; }
.dashboard-rank > div:first-child { display: flex; justify-content: space-between; gap: .5rem; margin-bottom: .375rem; font-size: .75rem; }
.dashboard-rank small { font-size: .625rem; color: var(--color-muted); margin-right: .625rem; }
.dashboard-rank strong { font-weight: 400; }
.dashboard-meter { height: .25rem; border-radius: .125rem; background: color-mix(in srgb, var(--color-border) 25%, transparent); overflow: hidden; }
.dashboard-meter > span { display: block; height: 100%; background: var(--color-accent); }
.dashboard-rank:nth-child(n+2) .dashboard-meter > span { opacity: .65; }
