.dashboard-agent-list > div { display: grid; grid-template-columns: 1fr auto 3.25rem; gap: .75rem; padding: .5rem 0; font-size: .75rem; border-bottom: 1px solid color-mix(in srgb, var(--color-border) 30%, transparent); }
.dashboard-agent-list > div:last-child { border: 0; }
.dashboard-agent-list > div > span:nth-child(2) { color: var(--color-muted); }
.dashboard-agent-list strong { font-weight: 400; text-align: right; }
.dashboard-data { margin-top: 1rem; color: var(--color-muted); font-size: .75rem; }
.dashboard-data summary { cursor: pointer; width: fit-content; padding: .5rem 0; }
.dashboard-data summary span { margin-left: .5rem; opacity: .7; }
.dashboard-table-scroll { overflow-x: auto; margin-top: .75rem; }
.dashboard-data table { border-collapse: collapse; width: 100%; white-space: nowrap; }
.dashboard-data th, .dashboard-data td { text-align: right; padding: .5rem .75rem; border-bottom: 1px solid var(--color-border); font-weight: 400; }
.dashboard-data th:first-child { text-align: left; }
.dashboard-state { padding: 2rem; font-size: .875rem; }
.dashboard-state h2 { font-size: 1.5rem; margin-bottom: .75rem; }
.dashboard-state .button { margin-top: 1rem; }
@media (min-width: 1024px) and (max-width: 1279px) {
  .dashboard-heading { align-items: flex-start; flex-direction: column; }
  .dashboard-card { padding: 1rem; }
  .dashboard-metric { grid-column: span 6; }
  .dashboard-wide, .dashboard-third { grid-column: span 6; }
