  .dashboard-controls { width: 100%; justify-content: space-between; }
  .dashboard-period { flex-wrap: wrap; }
  .dashboard-grid { gap: .625rem; }
  .dashboard-metric { grid-column: span 6; }
  .dashboard-wide, .dashboard-third { grid-column: span 12; }
  .dashboard-card { padding: 1rem; }
  .dashboard-metric h2 { font-size: .875rem; }
  .dashboard-metric-bottom > span { font-size: .625rem; }
  .dashboard-spark { width: 30%; }
  .dashboard-tag { font-size: .625rem; }
}
@media (prefers-reduced-motion: reduce) { .dashboard-bar { transition: none; } }
