@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

/*
 * One dark palette for the whole app, carried over from the landing page's
 * "stained" state: navy field, cyan membrane, violet myelin, magenta synapse.
 * shadcn components read these tokens.
 */
:root {
  color-scheme: dark;
  --radius: 0.75rem;
  --background: oklch(0.16 0.03 258);
  --foreground: oklch(0.97 0.005 250);
  --card: oklch(0.2 0.035 258 / 0.78);
  --card-foreground: oklch(0.97 0.005 250);
  --popover: oklch(0.2 0.035 258);
  --popover-foreground: oklch(0.97 0.005 250);
  --primary: oklch(0.89 0.11 205);
  --primary-foreground: oklch(0.2 0.04 258);
  --secondary: oklch(0.26 0.035 258);
  --secondary-foreground: oklch(0.97 0.005 250);
  --muted: oklch(0.26 0.035 258);
  --muted-foreground: oklch(0.74 0.025 255);
  --accent: oklch(0.28 0.045 245);
  --accent-foreground: oklch(0.97 0.005 250);
  --destructive: oklch(0.7 0.19 5);
  --border: oklch(1 0 0 / 11%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.89 0.11 205 / 60%);
  --chart-1: oklch(0.84 0.12 205); /* cyan: membrane / primary series */
  --chart-2: oklch(0.79 0.1 280); /* violet: myelin */
  --chart-3: oklch(0.72 0.19 355); /* magenta: synapse */
  --chart-4: oklch(0.83 0.13 80); /* amber */
  --chart-5: oklch(0.65 0.03 255); /* slate */
  --sidebar: oklch(0.17 0.035 258 / 0.86);
  --sidebar-foreground: oklch(0.97 0.005 250);
  --sidebar-primary: oklch(0.89 0.11 205);
  --sidebar-primary-foreground: oklch(0.2 0.04 258);
  --sidebar-accent: oklch(0.89 0.11 205 / 10%);
  --sidebar-accent-foreground: oklch(0.97 0.005 250);
  --sidebar-border: oklch(1 0 0 / 11%);
  --sidebar-ring: oklch(0.89 0.11 205 / 60%);

  /* status, never the only carrier: always paired with a text label */
  --status-flag: var(--chart-3);
  --status-watch: var(--chart-4);
  --status-stable: var(--chart-1);

  --p: 0; /* landing: 0 = grey, 1 = fluorescent; driven from Landing as the neuron fires */
  --glow: color-mix(in oklab, #86f2ff calc(var(--p) * 100%), #cbd5e1);
}

@theme inline {
  --font-sans: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --font-heading: "Sora", ui-sans-serif, system-ui, sans-serif;
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --color-foreground: var(--foreground);
  --color-background: var(--background);
  --color-flag: var(--status-flag);
  --color-watch: var(--status-watch);
  --color-stable: var(--status-stable);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
}

@layer base {
  * { @apply border-border outline-ring/50; }
  html, body, #root { height: 100%; }
  body {
    @apply bg-background text-foreground font-sans antialiased;
    margin: 0;
    overflow: hidden;
  }
  h1, h2, h3, .font-heading { font-family: var(--font-heading); }
}

@layer components {
  /* calhacks .eyebrow */
  .eyebrow {
    font-size: 0.6875rem;
    font-weight: 500;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--primary);
  }

  /* Translucent surfaces over the grain field (calhacks: quiet background behind the workspace). */
  [data-slot="sidebar-inner"], [data-slot="card"] {
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
  }
}

/* ---------------- landing ---------------- */

.app { position: relative; height: 100dvh; width: 100%; overflow: hidden; isolation: isolate; background: #111; }
.layer { position: absolute; inset: 0; }
.grain { z-index: 0; pointer-events: none; }
.ripples { z-index: 1; pointer-events: none; overflow: hidden; }
.stage { z-index: 2; }

.hero {
  position: absolute;
  z-index: 3;
  left: max(8vw, env(safe-area-inset-left));
  bottom: max(12vh, env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  pointer-events: none;
}
.hero button { pointer-events: auto; }

.title {
  margin: 0 0 1.5rem;
  min-height: 1.1em;
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -1.5px;
}
.title > span:first-child {
  background: linear-gradient(to right, #ffffff, #cbd5e1);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.cursor { margin-left: 2px; font-weight: 300; color: var(--glow); animation: blink 1.1s steps(1, end) infinite; }

.reveal { opacity: 0; transform: translateY(48px); transition: opacity 750ms cubic-bezier(0.22, 1, 0.36, 1) 350ms, transform 750ms cubic-bezier(0.22, 1, 0.36, 1) 350ms; }
.reveal.in { opacity: 1; transform: none; }

.auth-button {
  display: flex;
  align-items: center;
  gap: 14px;
  min-height: 48px;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  background: #fff;
  color: #3c4043;
  font: 500 16px/1.2 var(--font-sans);
  cursor: pointer;
  box-shadow: 0 2px 8px rgb(0 0 0 / 0.15);
  /* card.io: the Google logo starts greyscale and gains colour with the page. */
  filter: grayscale(calc((1 - var(--p)) * 100%));
  transition: transform 200ms ease-out, box-shadow 200ms ease-out;
}
.auth-button:active:not(:disabled) { transform: translateY(1px); }
.auth-button:focus-visible { outline: 2px solid var(--glow); outline-offset: 3px; }
.auth-button:disabled { cursor: not-allowed; opacity: 0.7; }
@media (hover: hover) {
  .auth-button:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 0 6px 20px rgb(0 0 0 / 0.2); }
}

.auth-note { margin: 12px 0 0; font-size: 13px; color: rgb(226 232 240 / 0.6); }

.ripple {
  position: absolute;
  width: 200vmax;
  height: 200vmax;
  border-radius: 50%;
  background: radial-gradient(circle, transparent 40%, rgb(255 255 255 / 0.06) 55%, rgb(255 255 255 / 0.1) 65%, rgb(255 255 255 / 0.06) 75%, transparent 90%);
  transform: translate(-50%, -50%) scale(0);
  animation: ripple 3s cubic-bezier(0.2, 0.6, 0.35, 1) forwards;
}

@keyframes ripple {
  from { transform: translate(-50%, -50%) scale(0); opacity: 1; }
  to { transform: translate(-50%, -50%) scale(1); opacity: 0; }
}

@keyframes blink { 50% { opacity: 0; } }

@media (max-width: 768px) {
  .hero { left: 20px; right: 20px; bottom: max(32px, env(safe-area-inset-bottom)); align-items: center; text-align: center; }
  .title { font-size: clamp(2.25rem, 11vw, 3rem); }
  .reveal { width: 100%; display: flex; flex-direction: column; align-items: center; }
  .auth-button { width: 100%; max-width: 340px; justify-content: center; }
}

@media (prefers-reduced-motion: reduce) {
  .reveal, .auth-button { transition: none; }
  .cursor, .ripple { animation: none; }
  .ripple { display: none; }
}

import { createContext, useContext, useEffect, useState, type ReactNode } from 'react'
import type { User } from '@supabase/supabase-js'
import { supabase } from './supabase'

/** Where Google sends people back to. Must be in Supabase → Auth → URL Configuration → Redirect URLs. */
export const AFTER_SIGN_IN = '/home'

type Auth = {
  user: User | null
  loading: boolean
  configured: boolean
  signInWithGoogle: () => Promise<string | null>
  signOut: () => Promise<void>
}

const AuthContext = createContext<Auth | null>(null)

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null)
  const [loading, setLoading] = useState(Boolean(supabase))

  useEffect(() => {
    if (!supabase) return
    // supabase-js reads the OAuth result from the URL when Google redirects back to /home.
    supabase.auth.getSession().then(({ data }) => {
      setUser(data.session?.user ?? null)
      setLoading(false)
    })
    const { data } = supabase.auth.onAuthStateChange((_event, session) => setUser(session?.user ?? null))
    return () => data.subscription.unsubscribe()
  }, [])

  const value: Auth = {
    user,
    loading,
    configured: Boolean(supabase),
    async signInWithGoogle() {
      if (!supabase) return 'Sign-in is not configured.'
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: { redirectTo: `${window.location.origin}${AFTER_SIGN_IN}` },
      })
      return error ? 'We couldn’t connect. Please try again.' : null
    },
    async signOut() {
      await supabase?.auth.signOut()
    },
  }

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

export function useAuth() {
  const ctx = useContext(AuthContext)
  if (!ctx) throw new Error('useAuth must be used inside <AuthProvider>')
  return ctx
}

