import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import type { NeuronData } from './neuron'

/**
 * Adapts "Neuron Cell Low-poly Simple" (vitalik.kucha, CC BY 4.0 — see
 * public/models/neuron.LICENSE.txt) to the firing simulation.
 *
 * The model is one merged mesh with no part names, so the parts are found
 * geometrically in its own coordinates: long axis = x, soma + dendrites at
 * x < −0.3, a straight axon to x ≈ 1.35, terminals beyond.
 */

export const MODEL_URL = '/models/neuron.glb'

const SOMA = new THREE.Vector3(-1.0, 0.0, 0.2) // densest blob, measured from the vertices
const SOMA_R = 0.6
const HILLOCK_X = -0.3
const AXON_END_X = 1.35
const SCALE = 3 // match the procedural neuron's scene units

export async function loadModelNeuron(): Promise<NeuronData> {
  const gltf = await new GLTFLoader().loadAsync(MODEL_URL)
  let source: THREE.BufferGeometry | undefined
  gltf.scene.traverse((o) => {
    if (!source && (o as THREE.Mesh).isMesh) source = (o as THREE.Mesh).geometry
  })
  if (!source) throw new Error('neuron.glb has no mesh')

  const geo = source.clone()
  geo.deleteAttribute('uv')
  const pos = geo.attributes.position as THREE.BufferAttribute
  const p = new THREE.Vector3()

  // Path distance from the soma: dendrites negative, soma 0, axon + terminals positive.
  const hillockGap = Math.max(0, Math.abs(HILLOCK_X - SOMA.x) - SOMA_R)
  const dist = new Float32Array(pos.count)
  for (let i = 0; i < pos.count; i++) {
    p.fromBufferAttribute(pos, i)
    dist[i] = p.x < HILLOCK_X
      ? -Math.max(0, p.distanceTo(SOMA) - SOMA_R) * SCALE
      : (p.x - HILLOCK_X + hillockGap) * SCALE
  }
  geo.setAttribute('aDist', new THREE.BufferAttribute(dist, 1))

  // Raw-space landmarks, collected before the transform.
  const raw = Array.from({ length: pos.count }, (_, i) => new THREE.Vector3().fromBufferAttribute(pos, i))

  // Axon centreline from slice centroids.
  const axonRaw: THREE.Vector3[] = []
  for (let x = HILLOCK_X; x <= AXON_END_X; x += 0.15) {
    const slice = raw.filter((v) => v.x >= x - 0.1 && v.x < x + 0.1)
    if (!slice.length) continue
    const c = slice.reduce((a, v) => a.add(v), new THREE.Vector3()).divideScalar(slice.length)
    axonRaw.push(c)
  }
  const axonEndRaw = axonRaw[axonRaw.length - 1]

  // Dendrite tips: farthest-point sample of vertices well away from the soma.
  const dendriteRaw = raw.filter((v) => v.x < HILLOCK_X && v.distanceTo(SOMA) > SOMA_R * 2.2)
  const tipsRaw = farthestPoints(dendriteRaw, 24)

  // Terminal boutons: farthest-point sample of the terminal spray.
  const terminalRaw = raw.filter((v) => v.x > AXON_END_X && v.distanceTo(axonEndRaw) > 0.45)
  const boutonRaw = farthestPoints(terminalRaw, 9)

  // Model space: soma at origin, z-up → y-up (the author's node rotation), scaled.
  const toScene = (v: THREE.Vector3) => v.clone().sub(SOMA).applyAxisAngle(new THREE.Vector3(1, 0, 0), -Math.PI / 2).multiplyScalar(SCALE)
  geo.translate(-SOMA.x, -SOMA.y, -SOMA.z)
  geo.rotateX(-Math.PI / 2)
  geo.scale(SCALE, SCALE, SCALE)

  const soma = toScene(SOMA)
  const axonCurve = new THREE.CatmullRomCurve3(axonRaw.map(toScene))
  const inputs = tipsRaw.map((t) => {
    const tip = toScene(t)
    return new THREE.CatmullRomCurve3([tip, tip.clone().lerp(soma, 0.5), soma])
  })
  const axonEnd = toScene(axonEndRaw)
  const boutons = boutonRaw.map((b) => {
    const pos = toScene(b)
    return { pos, dir: pos.clone().sub(axonEnd).normalize(), dist: (b.x - HILLOCK_X + hillockGap) * SCALE }
  })

  const empty = new THREE.BufferGeometry()
  return {
    soma: geo,
    dendrites: empty,
    axon: empty,
    myelin: empty,
    somaRadius: 0, // the model brings its own nucleus-less soma; no procedural nucleus
    nucleusOffset: new THREE.Vector3(),
    inputs,
    axonCurve,
    axonLength: axonCurve.getLength(),
    boutons,
    maxDist: Math.max(...dist),
  }
}

function farthestPoints(points: THREE.Vector3[], n: number) {
  if (!points.length) return []
  const picked = [points[0]]
  const best = points.map((p) => p.distanceToSquared(points[0]))
  while (picked.length < Math.min(n, points.length)) {
    let k = 0
    for (let i = 1; i < best.length; i++) if (best[i] > best[k]) k = i
    picked.push(points[k])
    for (let i = 0; i < points.length; i++) best[i] = Math.min(best[i], points[i].distanceToSquared(points[k]))
  }
  return picked
}

