import { Suspense, useEffect, useMemo } from 'react'
import { Canvas, useFrame, useLoader, useThree } from '@react-three/fiber'
import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'

/**
 * Callio Labs' DNA viewer, holding a neuron instead.
 * Model: "Neuron Cell Low-poly Simple" by vitalik.kucha, CC BY 4.0
 * (public/models/neuron.LICENSE.txt).
 */

const MODEL_URL = '/models/neuron.glb'
const MODEL_SIZE = 18 // largest dimension, world units
const COLOR = 0x606060
const OPACITY = 0.5
const VIEW_TILT_DEG = 30
const AUTO_ROTATE_SPEED = 3

function Neuron({ onLoaded }: { onLoaded?: () => void }) {
  const gltf = useLoader(GLTFLoader, MODEL_URL)

  const { model, center, scale } = useMemo(() => {
    const model = gltf.scene.clone(true)
    model.updateMatrixWorld(true)
    const box = new THREE.Box3().setFromObject(model)
    const size = box.getSize(new THREE.Vector3())
    return { model, center: box.getCenter(new THREE.Vector3()), scale: MODEL_SIZE / (Math.max(size.x, size.y, size.z) || 1) }
  }, [gltf])

  useEffect(() => {
    const color = new THREE.Color(COLOR)
    model.traverse((node) => {
      const mesh = node as THREE.Mesh
      if (!mesh.isMesh) return
      mesh.frustumCulled = false
      for (const m of Array.isArray(mesh.material) ? mesh.material : [mesh.material]) {
        if ('color' in m && m.color instanceof THREE.Color) m.color.copy(color)
        m.transparent = true
        m.opacity = OPACITY
        m.depthWrite = false
      }
    })
    onLoaded?.()
  }, [model, onLoaded])

  return (
    <group scale={scale}>
      <group position={[-center.x, -center.y, -center.z]}>
        <primitive object={model} />
      </group>
    </group>
  )
}

/** three's OrbitControls, as Callio uses via drei: auto-rotate, drag to spin, no zoom. */
function Controls({ autoRotate }: { autoRotate: boolean }) {
  const { camera, gl } = useThree()
  const controls = useMemo(() => new OrbitControls(camera, gl.domElement), [camera, gl])
  useEffect(() => {
    controls.autoRotate = autoRotate
    controls.autoRotateSpeed = AUTO_ROTATE_SPEED
    controls.enableZoom = false
    controls.enableDamping = true
    controls.minPolarAngle = Math.PI * 0.3
    controls.maxPolarAngle = Math.PI * 0.7
    return () => controls.dispose()
  }, [controls, autoRotate])
  useFrame(() => controls.update())
  return null
}

export default function NeuronViewer({ onLoaded, reducedMotion = false }: { onLoaded?: () => void; reducedMotion?: boolean }) {
  return (
    <div className="absolute inset-0 overflow-hidden" style={{ cursor: 'grab' }}>
      {/* Oversized and tilted like Callio's DNA, so the cell runs corner to corner. */}
      <div
        className="absolute"
        style={{
          left: '50%',
          top: '50%',
          width: '145%',
          height: '145%',
          transform: `translate(calc(-50% + 12%), calc(-50% + 2%)) rotate(-${VIEW_TILT_DEG}deg)`,
        }}
      >
        <Canvas
          camera={{ position: [0, 0, 12], fov: 65 }}
          dpr={[1, 2]}
          gl={{ alpha: true, antialias: true, logarithmicDepthBuffer: true }}
          style={{ width: '100%', height: '100%' }}
        >
          <ambientLight intensity={2} />
          <directionalLight position={[8, 8, 6]} intensity={3} />
          <directionalLight position={[-8, 6, 4]} intensity={2} />
          <directionalLight position={[0, -10, 2]} intensity={1.5} />
          <pointLight position={[0, 0, 8]} intensity={2} />
          <Controls autoRotate={!reducedMotion} />
          <Suspense fallback={null}>
            <Neuron onLoaded={onLoaded} />
          </Suspense>
        </Canvas>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'

/** Callio Labs' white splash: wordmark + three dots, fades once ready and a minimum time has passed. */
export function Splash({ ready = true, minMs = 2000 }: { ready?: boolean; minMs?: number }) {
  const [minReached, setMinReached] = useState(false)
  const [fading, setFading] = useState(false)
  const [done, setDone] = useState(false)

  useEffect(() => {
    const t = setTimeout(() => setMinReached(true), minMs)
    return () => clearTimeout(t)
  }, [minMs])

  useEffect(() => {
    if (minReached && ready) setFading(true)
  }, [minReached, ready])

  if (done) return null
  return (
    <div
      className={`fixed inset-0 z-[9999] bg-white ${fading ? 'animate-splash-fade-out' : ''}`}
      onAnimationEnd={() => fading && setDone(true)}
      aria-hidden
    >
      <div className="absolute top-1/2 left-1/2 flex -translate-x-1/2 -translate-y-1/2 flex-col items-center gap-6 text-black">
        <span className="font-brand text-5xl tracking-tight md:text-6xl">motus</span>
        <div className="flex items-center gap-1.5">
          <span className="animate-loading-dot-1 size-2 rounded-full bg-black/80" />
          <span className="animate-loading-dot-2 size-2 rounded-full bg-black/80" />
          <span className="animate-loading-dot-3 size-2 rounded-full bg-black/80" />
        </div>
      </div>
    </div>
  )
}

