/** Callio Labs' landing: dithered field, one 3D object, wordmark + glass sign-in pill bottom-left. */
export default function Landing() {
  const { user, configured, signInWithGoogle } = useAuth()
  const [modelLoaded, setModelLoaded] = useState(false)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')

  if (user) return <Navigate to={AFTER_SIGN_IN} replace />

  async function onSignIn() {
    setBusy(true)
    setError('')
    const failed = await signInWithGoogle()
    if (failed) {
      setError(failed)
      setBusy(false)
    }
  }

  return (
    <div className="relative h-dvh w-screen overflow-hidden bg-white text-black">
      <div className="absolute inset-0 z-0">
        <Dither
          waveSpeed={0.02}
          waveFrequency={3}
          waveAmplitude={0.3}
          backgroundColor={[1, 1, 1]}
          waveColor={[0, 0, 0]}
          colorNum={4}
          pixelSize={2}
          disableAnimation={reducedMotion}
          enableMouseInteraction
          mouseRadius={1.2}
        />
      </div>
      <div className="absolute inset-0 z-0">
        <NeuronViewer onLoaded={() => setModelLoaded(true)} reducedMotion={reducedMotion} />
      </div>

      <main className="pointer-events-none absolute bottom-0 left-0 z-10 flex flex-col items-start pb-12 pl-12 md:pb-16 md:pl-16 lg:pb-20 lg:pl-20">
        <h1 className="font-brand text-6xl leading-none md:text-7xl lg:text-8xl">motus</h1>
        <p className="font-serif-display -mt-1 text-xl leading-none opacity-70 md:-mt-1.5 md:text-2xl lg:-mt-2 lg:text-3xl">
          early ALS detection
        </p>
        <GlassSurface
          width={'fit-content' as unknown as number}
          height={'fit-content' as unknown as number}
          borderRadius={20}
          className="pointer-events-auto mt-5 md:mt-6"
          contentClassName="p-0 !items-center !justify-center"
        >
          <button
            type="button"
            onClick={onSignIn}
            disabled={!configured || busy}
            aria-busy={busy}
            className="font-serif-display flex cursor-pointer items-center gap-2 border-0 bg-transparent px-3 py-2 text-xs tracking-wide text-black/90 transition-colors hover:text-black disabled:cursor-not-allowed disabled:opacity-60"
          >
            <GoogleIcon />
            {busy ? 'Connecting…' : 'Sign in with Google'}
          </button>
        </GlassSurface>
        {error ? <p className="mt-3 text-xs text-black/70" role="alert">{error}</p> : null}
        {!configured ? <p className="mt-3 text-xs text-black/60">Add Supabase keys to .env to enable sign-in.</p> : null}
      </main>

      {/* CC BY 4.0 attribution for the neuron model (public/models/neuron.LICENSE.txt). */}
      <p className="absolute right-5 bottom-4 z-10 text-[11px] text-black/45 [&_a]:underline [&_a]:decoration-black/25 [&_a]:underline-offset-2 [&_a:hover]:text-black/80">
        <a href="https://sketchfab.com/3d-models/neuron-cell-low-poly-simple-3a09438daf364c3bbd3cce76f1c7afaa" target="_blank" rel="noreferrer">Neuron Cell Low-poly Simple</a>
        {' by '}
        <a href="https://sketchfab.com/vitalik.kucha" target="_blank" rel="noreferrer">vitalik.kucha</a>
        {' · '}
        <a href="http://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>
      </p>

      <Splash ready={modelLoaded} />
    </div>
  )
}

