// Render the landing's neuron to icon PNGs via headless Chrome (CDP).
// usage: node make-icons.mjs <url> <outDir>
import { spawn } from 'node:child_process'
import { writeFileSync, mkdtempSync } from 'node:fs'
import { join } from 'node:path'
import { tmpdir } from 'node:os'

const [url, outDir] = process.argv.slice(2)
const port = 9334
const prof = mkdtempSync(join(tmpdir(), 'cdp-icons-'))
const chrome = spawn('C:/Program Files/Google/Chrome/Application/chrome.exe', [
  '--headless=new', `--remote-debugging-port=${port}`, '--window-size=1440,900',
  '--use-angle=swiftshader', '--enable-unsafe-swiftshader', `--user-data-dir=${prof}`, 'about:blank',
], { stdio: 'ignore' })
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
let targets
for (let i = 0; i < 40; i++) {
  try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); break } catch { await sleep(250) }
}
const ws = new WebSocket(targets.find((t) => t.type === 'page').webSocketDebuggerUrl)
await new Promise((r) => ws.addEventListener('open', r))
let id = 0
const pending = new Map()
ws.addEventListener('message', (e) => {
  const m = JSON.parse(e.data)
  if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id) }
})
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })) })
const evalJs = async (expression) => (await send('Runtime.evaluate', { expression, returnByValue: true })).result?.result?.value
const shot = async (file, clip) => {
  const r = await send('Page.captureScreenshot', { format: 'png', clip, captureBeyondViewport: false })
  writeFileSync(join(outDir, file), Buffer.from(r.result.data, 'base64'))
  console.log('wrote', file)
}

await send('Page.enable')
await send('Runtime.enable')
// Reduced motion: no spin, no firing, so the icon is the calm, resting cell.
await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'reduce' }] })

// 1) Link preview (1200x630), the landing as a visitor sees it.
await send('Emulation.setDeviceMetricsOverride', { width: 1200, height: 630, deviceScaleFactor: 1, mobile: false })
await send('Page.navigate', { url })
await sleep(9000)
await shot('og-image.png', { x: 0, y: 0, width: 1200, height: 630, scale: 1 })

// 2) Icons: the neuron alone on paper, cropped to the soma and dendrite crown.
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 2, mobile: false })
await send('Page.navigate', { url })
await sleep(4000)
await evalJs(`(() => {
  document.querySelector('.dither-container').style.display = 'none'
  document.querySelector('main').style.display = 'none'
  document.querySelectorAll('p').forEach((p) => (p.style.display = 'none'))
})()`)
await sleep(5000)
const box = { x: 712, y: 18, size: 476 } // soma + dendrites, measured from a 1440x900 render
for (const [file, px] of [['icon-512.png', 512], ['icon-192.png', 192], ['apple-touch-icon.png', 180], ['favicon-32.png', 32]]) {
  await shot(file, { x: box.x, y: box.y, width: box.size, height: box.size, scale: px / box.size / 2 })
}

ws.close()
chrome.kill()
process.exit(0)

