import { createContext, useCallback, useContext, useEffect, useReducer, useRef, useState, type ReactNode } from 'react'
import type { CaseFile } from './case-pdf'
import {
  SAMPLE_PATIENT, runDemoPipeline,
  type AgentStep, type DrugProfile, type PipelineEvent, type StageId, type Weights,
} from './pipeline'

/**
 * One discovery run, shared by every pipeline page (case → analysis → profiles →
 * embedding → candidates → report). Lives above the pages so the run keeps going
 * while you move between them.
 */

export type StageStatus = 'pending' | 'running' | 'done'
export type TraceItem = { stage: StageId; lane?: number; step: AgentStep }
export type CompletedRun = { id: string; date: string; weights: Weights; goal: string; caseName: string | null }

export type RunState = {
  phase: 'idle' | 'running' | 'done'
  stages: Record<StageId, StageStatus>
  trace: TraceItem[]
  profiles: DrugProfile[]
  matches: boolean
  candidates: boolean
  report: boolean
}

const initial: RunState = {
  phase: 'idle',
  stages: { analysis: 'pending', profiles: 'pending', embedding: 'pending', research: 'pending', report: 'pending' },
  trace: [],
  profiles: [],
  matches: false,
  candidates: false,
  report: false,
}

type Action = PipelineEvent | { type: 'start' } | { type: 'finish' } | { type: 'reset' }

function reducer(s: RunState, a: Action): RunState {
  switch (a.type) {
    case 'reset':
      return initial
    case 'start':
      return { ...initial, phase: 'running' }
    case 'finish':
      return { ...s, phase: 'done' }
    case 'stage':
      return { ...s, stages: { ...s.stages, [a.stage]: a.status } }
    case 'step':
      return { ...s, trace: [...s.trace, { stage: a.stage, lane: a.lane, step: a.step }] }
    case 'profile':
      return { ...s, profiles: [...s.profiles, a.profile].sort((x, y) => x.lane - y.lane) }
    case 'matches':
      return { ...s, matches: true }
    case 'candidates':
      return { ...s, candidates: true }
    case 'report':
      return { ...s, report: true }
  }
}

export const DEFAULT_GOAL =
  'Find approved or late-stage drugs that could slow progression or ease bulbar symptoms for this patient, now that MRgFUS can open the blood–brain barrier over motor cortex.'

type Store = {
  state: RunState
  caseFile: CaseFile | null
  setCaseFile: (f: CaseFile | null) => void
  goal: string
  setGoal: (g: string) => void
  weights: Weights
  setWeights: (w: Weights) => void
  date: string
  runs: CompletedRun[]
  start: () => void
  skip: () => void
  reset: () => void
}

const Ctx = createContext<Store | null>(null)

export function RunProvider({ children, onStage }: { children: ReactNode; onStage?: (stage: StageId) => void }) {
  const [state, dispatch] = useReducer(reducer, initial)
  const [caseFile, setCaseFile] = useState<CaseFile | null>(null)
  const [goal, setGoal] = useState(DEFAULT_GOAL)
  const [weights, setWeights] = useState<Weights>({ fit: true, safety: true, cost: true, availability: true, acceptance: true })
  const [date, setDate] = useState('')
  const [runs, setRuns] = useState<CompletedRun[]>([])
  const runner = useRef<{ cancel: () => void; skip: () => void } | null>(null)
  const onStageRef = useRef(onStage)
  onStageRef.current = onStage

  useEffect(() => () => runner.current?.cancel(), [])

  const start = useCallback(() => {
    runner.current?.cancel()
    dispatch({ type: 'start' })
    const when = new Intl.DateTimeFormat('en-CA', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date())
    setDate(when)
    const caseInput = caseFile
      ? { name: caseFile.name, pages: caseFile.pages, words: caseFile.words, excerpt: caseFile.text.join(' ').slice(0, 220).trim() }
      : null
    runner.current = runDemoPipeline(
      SAMPLE_PATIENT,
      caseInput,
      (e) => {
        dispatch(e)
        if (e.type === 'stage' && e.status === 'running') onStageRef.current?.(e.stage)
      },
      () => {
        dispatch({ type: 'finish' })
        setRuns((r) => [{ id: crypto.randomUUID(), date: when, weights, goal, caseName: caseFile?.name ?? null }, ...r])
      },
    )
  }, [caseFile, goal, weights])

  const skip = useCallback(() => runner.current?.skip(), [])
  const reset = useCallback(() => {
    runner.current?.cancel()
    dispatch({ type: 'reset' })
  }, [])

  return (
    <Ctx.Provider value={{ state, caseFile, setCaseFile, goal, setGoal, weights, setWeights, date, runs, start, skip, reset }}>
      {children}
    </Ctx.Provider>
  )
}

export function useRun() {
  const ctx = useContext(Ctx)
  if (!ctx) throw new Error('useRun must be used inside <RunProvider>')
  return ctx
}

import { useEffect, useRef, useState, type ReactNode } from 'react'
import { Brain, Check, ChevronRight, Circle, FastForward, Loader2, MessageSquare, RotateCcw, Terminal, Wrench, Zap } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Card, CardAction, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { cn } from '@/lib/utils'
import { SAMPLE_PATIENT, STAGES, type StageId } from '@/lib/pipeline'
import { useRun, type TraceItem } from '@/lib/run-store'
import { LANE_COLORS } from './lanes'

export const AMBER = '#c9732a'

const STEP_ICON = { thinking: Brain, tool_call: Wrench, tool_result: Terminal, output: MessageSquare }
const STEP_TONE = { thinking: 'text-chart-4', tool_call: 'text-[#c9732a]', tool_result: 'text-[#3f7d4e]', output: 'text-foreground' }

/** Page header shared by every pipeline page: eyebrow, title, run controls, progress rail. */
export function StageHeader({ step, title, description, rail = true }: { step: string; title: string; description: string; rail?: boolean }) {
  const { state, skip, reset } = useRun()
  return (
    <div className="space-y-3">
      <div className="rounded-xl bg-card px-5 pt-5 pb-4 ring-1 ring-border backdrop-blur-md">
        <div className="flex flex-wrap items-end justify-between gap-4">
          <div>
            <p className="eyebrow">Pipeline / {step}</p>
            <h2 className="font-brand mt-3 text-[clamp(2rem,3.2vw,3rem)] leading-none">{title}</h2>
            <p className="mt-3 max-w-2xl text-muted-foreground">{description}</p>
          </div>
          <div className="flex items-center gap-2">
            <Badge variant="outline" className="border-watch/40 bg-watch/10 font-normal text-watch">Simulated run</Badge>
            {state.phase === 'running' ? (
              <Button size="sm" variant="outline" onClick={skip}>
                <FastForward aria-hidden /> Skip to results
              </Button>
            ) : state.phase === 'done' ? (
              <Button size="sm" variant="outline" onClick={reset}>
                <RotateCcw aria-hidden /> Clear run
              </Button>
            ) : null}
          </div>
        </div>
      </div>
      {rail ? <PipelineRail /> : null}
    </div>
  )
}

export function PipelineRail() {
  const { state } = useRun()
  return (
    <ol className="grid grid-cols-5 gap-2" aria-label="Pipeline progress">
      {STAGES.map((s, i) => {
        const st = state.stages[s.id]
        return (
          <li
            key={s.id}
            className={cn(
              'rounded-lg border bg-card px-3 py-2 backdrop-blur-md transition-colors',
              st === 'running' && 'border-[#c9732a]/60',
              st === 'done' && 'border-foreground/25',
            )}
          >
            <div className="flex items-center gap-2 text-xs text-muted-foreground">
              <span className="tabular-nums">{String(i + 1).padStart(2, '0')}</span>
              <StatusIcon status={st} />
              <span className="truncate text-foreground">{s.label}</span>
            </div>
            {s.id === 'profiles' ? (
              <div className="mt-1.5 flex gap-1" aria-hidden>
                {LANE_COLORS.map((c, l) => (
                  <span key={c} className="h-1 flex-1 rounded-full" style={{ background: c, opacity: l < state.profiles.length ? 1 : st === 'running' ? 0.35 : 0.2 }} />
                ))}
              </div>
            ) : null}
          </li>
        )
      })}
    </ol>
  )
}

export function StatusIcon({ status }: { status: 'pending' | 'running' | 'done' }) {
  if (status === 'done') return <Check className="size-3.5 shrink-0 text-foreground" aria-label="done" />
  if (status === 'running') return <Loader2 className="size-3.5 shrink-0 animate-spin text-[#c9732a]" aria-label="running" />
  return <Circle className="size-3 shrink-0 opacity-40" aria-label="pending" />
}

/** Shown on a stage page before its stage has started. */
export function EmptyStage({ after, onGo }: { after: string; onGo: () => void }) {
  const { state } = useRun()
  return (
    <Card className="items-start gap-3 [--card-spacing:--spacing(8)]">
      <CardContent className="space-y-3">
        <p className="eyebrow">Not started</p>
        <p className="max-w-lg text-muted-foreground">
          {state.phase === 'idle' ? 'Start a run from the patient case. ' : ''}This step runs after {after}.
        </p>
        {state.phase === 'idle' ? <Button onClick={onGo}>Go to patient case</Button> : null}
      </CardContent>
    </Card>
  )
}

function StepRow({ item }: { item: TraceItem }) {
  const [open, setOpen] = useState(false)
  const Icon = STEP_ICON[item.step.type]
  return (
    <div className="border-b border-border/60 last:border-b-0">
      <button type="button" onClick={() => setOpen((v) => !v)} className="flex w-full items-center gap-2 px-3 py-1.5 text-left hover:bg-foreground/[0.03]">
        <ChevronRight className={cn('size-3 shrink-0 text-muted-foreground transition-transform', open && 'rotate-90')} aria-hidden />
        {item.lane !== undefined ? <span className="size-1.5 shrink-0 rounded-full" style={{ background: LANE_COLORS[item.lane] }} /> : null}
        <Icon className={cn('size-3.5 shrink-0', STEP_TONE[item.step.type])} aria-hidden />
        <span className="truncate text-xs">{item.step.label}</span>
      </button>
      {open ? <pre className="px-3 pb-2 pl-9 font-sans text-xs leading-relaxed whitespace-pre-wrap text-muted-foreground">{item.step.content}</pre> : null}
    </div>
  )
}

/** Callio-style agent trace, filtered to one stage (and optionally one lane). */
export function Trace({ stage, lane, title = 'Agent trace', className, maxH = 'max-h-[28rem]' }: { stage: StageId; lane?: number; title?: string; className?: string; maxH?: string }) {
  const { state } = useRun()
  const items = state.trace.filter((t) => t.stage === stage && (lane === undefined || t.lane === lane))
  const running = state.stages[stage] === 'running'
  const ref = useRef<HTMLDivElement>(null)
  useEffect(() => {
    ref.current?.scrollTo({ top: ref.current.scrollHeight })
  }, [items.length])
  return (
    <Card className={cn('gap-0 py-0', className)}>
      <div className="flex items-center justify-between border-b px-4 py-3">
        <span className="text-sm font-medium">{title}</span>
        <span className="text-xs text-muted-foreground tabular-nums">{items.length} steps</span>
      </div>
      <div ref={ref} className={cn('overflow-y-auto', maxH)}>
        {items.length ? items.map((it, i) => <StepRow key={i} item={it} />) : <p className="px-4 py-3 text-xs text-muted-foreground">Waiting…</p>}
      </div>
      <div className="flex items-center gap-2 border-t px-3 py-2 text-xs text-muted-foreground">
        {running ? <><Loader2 className="size-3 animate-spin text-[#c9732a]" aria-hidden /> Working…</> : state.stages[stage] === 'done' ? 'Done.' : 'Queued.'}
      </div>
    </Card>
  )
}

/** Structured patient summary. In a live run the analysis agent fills this from the case PDF. */
export function PatientCard({ compact = false, footer }: { compact?: boolean; footer?: ReactNode }) {
  const p = SAMPLE_PATIENT
  const rows: [string, string][] = [
    ['Presentation', `${p.age}${p.sex} · ${p.onset} · ${p.monthsSinceDx} mo`],
    ['ALSFRS-R', `${p.alsfrs}/48 · ${p.slope} pts/mo`],
    ['FVC', `${p.fvc}% predicted`],
    ['Genetics', p.genetics],
    ['Medication', p.medications.join(', ')],
    ['Conditions', p.comorbidities.join(', ')],
    ['Location', `${p.location} · ${p.coverage}`],
  ]
  return (
    <Card className="gap-3 [--card-spacing:--spacing(5)]">
      <CardHeader>
        <CardTitle className="text-lg font-normal">{p.label}</CardTitle>
        <CardAction>
          {p.fusEligible ? (
            <Badge variant="outline" className="gap-1 border-[#c9732a]/40 bg-[#c9732a]/10 font-normal text-[#a35b1d]">
              <Zap className="size-3" aria-hidden /> MRgFUS eligible
            </Badge>
          ) : null}
        </CardAction>
      </CardHeader>
      <CardContent>
        <dl className={cn('grid grid-cols-[6.5rem_1fr] gap-x-3 gap-y-1.5 text-sm', compact && 'text-xs')}>
          {(compact ? rows.slice(0, 5) : rows).map(([k, v]) => (
            <div key={k} className="contents">
              <dt className="text-muted-foreground">{k}</dt>
              <dd>{v}</dd>
            </div>
          ))}
        </dl>
        {!compact ? (
          <div className="mt-4 flex flex-wrap gap-1.5">
            {p.preferences.map((x) => (
              <Badge key={x} variant="outline" className="font-normal">{x}</Badge>
            ))}
          </div>
        ) : null}
        {footer}
      </CardContent>
    </Card>
  )
}

import { useRef, useState } from 'react'
import { CartesianGrid, LabelList, Scatter, ScatterChart, Tooltip, XAxis, YAxis, ZAxis } from 'recharts'
import { ArrowRight, FileText, Loader2, Play, Upload, X } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Card, CardAction, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { ChartContainer } from '@/components/ui/chart'
import { Switch } from '@/components/ui/switch'
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table'
import { Textarea } from '@/components/ui/textarea'
import { cn } from '@/lib/utils'
import { readCasePdf } from '@/lib/case-pdf'
import { CANDIDATES, CRITERIA, EXCLUDED, MATCHES, PROFILE_POINTS, PROFILES, SAMPLE_PATIENT, rank } from '@/lib/pipeline'
import { useRun } from '@/lib/run-store'
import { LANE_COLORS } from './lanes'
import { EmptyStage, PatientCard, StageHeader, Trace } from './pieces'
import { Report } from './report'

type Go = (view: string) => void

/* ------------------------------------------------------------ 00 patient case */

function CaseUpload() {
  const { caseFile, setCaseFile, state } = useRun()
  const input = useRef<HTMLInputElement>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [drag, setDrag] = useState(false)
  const [page, setPage] = useState(0)
  const locked = state.phase === 'running'

  async function take(file: File | undefined) {
    if (!file) return
    if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) {
      setError('Please choose a PDF.')
      return
    }
    setBusy(true)
    setError('')
    try {
      setCaseFile(await readCasePdf(file))
      setPage(0)
    } catch {
      setError('Couldn’t read that PDF. Is it password-protected or a scanned image?')
    } finally {
      setBusy(false)
    }
  }

  if (caseFile) {
    const text = caseFile.text[page] ?? ''
    return (
      <Card className="gap-3 [--card-spacing:--spacing(5)]">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-lg font-normal">
            <FileText className="size-4 text-muted-foreground" aria-hidden /> {caseFile.name}
          </CardTitle>
          <CardAction>
            <Button size="icon-sm" variant="ghost" disabled={locked} onClick={() => setCaseFile(null)} aria-label="Remove case PDF">
              <X />
            </Button>
          </CardAction>
        </CardHeader>
        <CardContent className="space-y-3">
          <p className="text-xs text-muted-foreground">
            {caseFile.pages} page{caseFile.pages === 1 ? '' : 's'} · {caseFile.words.toLocaleString()} words · {caseFile.sizeKB} KB · read in your browser, not uploaded
          </p>
          <div className="max-h-64 overflow-y-auto rounded-lg border bg-background/70 p-3 text-xs leading-relaxed whitespace-pre-wrap">
            {text || <span className="text-muted-foreground">No text on this page (it may be a scanned image).</span>}
          </div>
          {caseFile.pages > 1 ? (
            <div className="flex items-center justify-between text-xs text-muted-foreground">
              <Button size="xs" variant="ghost" disabled={page === 0} onClick={() => setPage((p) => p - 1)}>Previous</Button>
              <span className="tabular-nums">Page {page + 1} of {caseFile.pages}</span>
              <Button size="xs" variant="ghost" disabled={page === caseFile.pages - 1} onClick={() => setPage((p) => p + 1)}>Next</Button>
            </div>
          ) : null}
        </CardContent>
      </Card>
    )
  }

  return (
    <div
      onDragOver={(e) => {
        e.preventDefault()
        setDrag(true)
      }}
      onDragLeave={() => setDrag(false)}
      onDrop={(e) => {
        e.preventDefault()
        setDrag(false)
        void take(e.dataTransfer.files[0])
      }}
      className={cn(
        'flex flex-col items-center justify-center gap-3 rounded-xl border-2 border-dashed bg-card px-6 py-12 text-center backdrop-blur-md transition-colors',
        drag ? 'border-[#c9732a] bg-[#c9732a]/5' : 'border-foreground/20',
      )}
    >
      {busy ? <Loader2 className="size-6 animate-spin text-muted-foreground" aria-hidden /> : <Upload className="size-6 text-muted-foreground" aria-hidden />}
      <div>
        <p className="font-medium">{busy ? 'Reading case…' : 'Drop the patient case PDF here'}</p>
        <p className="mt-1 text-xs text-muted-foreground">Clinic letters, genetics, medication list, ALSFRS-R history. Read in your browser; nothing is uploaded.</p>
      </div>
      <input ref={input} type="file" accept="application/pdf,.pdf" className="sr-only" onChange={(e) => void take(e.target.files?.[0])} />
      <Button variant="outline" size="sm" disabled={busy} onClick={() => input.current?.click()}>Choose PDF</Button>
      {error ? <p className="text-xs text-destructive" role="alert">{error}</p> : null}
    </div>
  )
}

export function CasePage({ go }: { go: Go }) {
  const { state, caseFile, goal, setGoal, weights, setWeights, start } = useRun()
  return (
    <div className="mx-auto max-w-[1440px] space-y-3 text-sm">
      <StageHeader
        step="00 · Patient case"
        title="Start with the patient."
        description="Add the patient’s case file. The analysis agent reads it first; every later step — profiles, matching, ranking — is shaped by it."
      />
      <div className="grid gap-3 lg:grid-cols-12">
        <div className="space-y-3 lg:col-span-6">
          <CaseUpload />
          <PatientCard
            footer={
              <p className="mt-4 border-t pt-3 text-xs text-muted-foreground">
                {caseFile
                  ? 'Simulated run: this structured profile is the built-in sample. The live analysis agent extracts it from the case PDF.'
                  : 'No case PDF yet — the run will use this built-in sample patient.'}
              </p>
            }
          />
        </div>
        <Card className="gap-4 self-start [--card-spacing:--spacing(5)] lg:col-span-6">
          <CardHeader>
            <CardTitle className="text-lg font-normal">Research goal</CardTitle>
          </CardHeader>
          <CardContent className="space-y-5">
            <Textarea value={goal} onChange={(e) => setGoal(e.target.value)} rows={4} className="bg-background/70 text-sm" aria-label="Research goal" />
            <div>
              <p className="mb-2 text-xs text-muted-foreground">Weigh candidates by</p>
              <div className="grid gap-2 sm:grid-cols-2">
                {CRITERIA.map((c) => (
                  <label key={c.key} className="flex items-start gap-3 rounded-lg border bg-background/50 px-3 py-2.5">
                    <Switch className="mt-0.5" checked={weights[c.key]} onCheckedChange={(v) => setWeights({ ...weights, [c.key]: v })} />
                    <span>
                      <span className="block text-sm">{c.label}</span>
                      <span className="block text-xs text-muted-foreground">{c.hint}</span>
                    </span>
                  </label>
                ))}
              </div>
            </div>
            <div className="flex flex-wrap items-center justify-between gap-3 border-t pt-4">
              <span className="max-w-xs text-xs text-muted-foreground">Delivery assumption: MR-guided focused ultrasound BBB opening (Sunnybrook)</span>
              {state.phase === 'running' ? (
                <Button variant="outline" onClick={() => go('analysis')}>
                  Run in progress <ArrowRight aria-hidden />
                </Button>
              ) : (
                <Button onClick={start} disabled={!goal.trim()}>
                  <Play aria-hidden /> {state.phase === 'done' ? 'Run again' : 'Run 5 agents'}
                </Button>
              )}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  )
}

/* -------------------------------------------------------- 01 patient analysis */

export function AnalysisPage({ go }: { go: Go }) {
  const { state, caseFile } = useRun()
  const summary = state.trace.find((t) => t.stage === 'analysis' && t.step.type === 'output')
  return (
    <div className="mx-auto max-w-[1440px] space-y-3 text-sm">
      <StageHeader
        step="01 · Patient analysis"
        title="Understand the case."
        description="The analysis agent reads the case file, checks genetics against NCBI and ClinVar, and writes the patient summary every other agent works from."
      />
      {state.stages.analysis === 'pending' ? (
        <EmptyStage after="the patient case is added" onGo={() => go('case')} />
      ) : (
        <div className="grid gap-3 lg:grid-cols-12">
          <div className="space-y-3 lg:col-span-5">
            <PatientCard compact />
            {caseFile ? (
              <Card className="gap-2 [--card-spacing:--spacing(4)]">
                <CardContent className="flex items-center gap-3 text-xs">
                  <FileText className="size-4 text-muted-foreground" aria-hidden />
                  <span className="truncate">{caseFile.name}</span>
                  <span className="ml-auto shrink-0 text-muted-foreground">{caseFile.pages} pp · {caseFile.words.toLocaleString()} words</span>
                </CardContent>
              </Card>
            ) : null}
          </div>
          <div className="space-y-3 lg:col-span-7">
            <Trace stage="analysis" title="Analysis agent" />
            {summary ? (
              <Card className="gap-2 [--card-spacing:--spacing(5)]">
                <CardHeader>
                  <CardTitle className="text-lg font-normal">Patient summary</CardTitle>
                  <CardAction>
                    <Button size="sm" variant="ghost" onClick={() => go('profiles')}>Profiles <ArrowRight aria-hidden /></Button>
                  </CardAction>
                </CardHeader>
                <CardContent><p>{summary.step.content}</p></CardContent>
              </Card>
            ) : null}
          </div>
        </div>
      )}
    </div>
  )
}

/* ---------------------------------------------------------- 02 profile agents */

export function ProfilesPage({ go }: { go: Go }) {
  const { state } = useRun()
  return (
    <div className="mx-auto max-w-[1600px] space-y-3 text-sm">
      <StageHeader
        step="02 · Profile agents"
        title="Five takes on the ideal drug."
        description="Five agents run in parallel. Each frames a different therapeutic hypothesis for this patient and writes the profile of the drug that would test it."
      />
      {state.stages.profiles === 'pending' ? (
        <EmptyStage after="patient analysis" onGo={() => go('case')} />
      ) : (
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5">
          {PROFILES.map((p) => {
            const ready = state.profiles.find((x) => x.lane === p.lane)
            return (
              <div key={p.lane} className="flex flex-col gap-3">
                <div className="rounded-lg border-t-4 bg-card px-4 py-3 ring-1 ring-border backdrop-blur-md" style={{ borderTopColor: LANE_COLORS[p.lane] }}>
                  <p className="text-xs text-muted-foreground">Agent {p.lane + 1}</p>
                  <p className="font-medium">{p.name}</p>
                </div>
                <Trace stage="profiles" lane={p.lane} title="Trace" maxH="max-h-48" />
                <div className={cn('rounded-lg bg-card p-4 ring-1 ring-border backdrop-blur-md transition-opacity', !ready && 'opacity-50')}>
                  {ready ? (
                    <>
                      <p className="text-sm">{ready.hypothesis}</p>
                      <dl className="mt-3 space-y-2 text-xs">
                        <div><dt className="text-muted-foreground">Targets</dt><dd>{ready.targets.join(', ')}</dd></div>
                        <div><dt className="text-muted-foreground">Modality</dt><dd>{ready.modality}</dd></div>
                        <div><dt className="text-muted-foreground">Constraints</dt><dd>{ready.constraints.join('; ')}</dd></div>
                      </dl>
                    </>
                  ) : (
                    <p className="flex items-center gap-2 text-xs text-muted-foreground"><Loader2 className="size-3 animate-spin" aria-hidden /> Writing profile…</p>
                  )}
                </div>
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

/* ---------------------------------------------------------- 03 DRKG embedding */

export function EmbeddingPage({ go }: { go: Go }) {
  const { state } = useRun()
  const drugs = MATCHES.map((m) => ({ ...m }))
  return (
    <div className="mx-auto max-w-[1440px] space-y-3 text-sm">
      <StageHeader
        step="03 · DRKG embedding"
        title="From profile to real compounds."
        description="Each profile becomes a vector in the DRKG knowledge-graph embedding space; the nearest drug entities by cosine similarity become candidates."
      />
      {state.stages.embedding === 'pending' ? (
        <EmptyStage after="the five profile agents" onGo={() => go('case')} />
      ) : (
        <div className="grid gap-3 lg:grid-cols-12">
          <div className="space-y-3 lg:col-span-8">
            <div className={cn('rounded-xl bg-card p-4 ring-1 ring-border backdrop-blur-md transition-opacity', !state.matches && 'opacity-40')}>
              <p className="text-xs text-muted-foreground">DRKG TransE embedding space · 2D projection</p>
              <ChartContainer config={{}} className="aspect-auto h-[22rem] w-full">
                <ScatterChart margin={{ top: 12, right: 32, bottom: 4, left: 0 }}>
                  <CartesianGrid strokeDasharray="3 6" />
                  <XAxis type="number" dataKey="x" domain={[-3.5, 3.5]} hide />
                  <YAxis type="number" dataKey="y" domain={[-3.5, 3.5]} hide />
                  <ZAxis range={[60, 60]} />
                  <Tooltip
                    cursor={false}
                    content={({ payload }) => {
                      const d = payload?.[0]?.payload as (typeof drugs)[number] | undefined
                      if (!d?.drug) return null
                      return <div className="rounded-md border bg-popover px-2 py-1 text-xs shadow-sm"><strong>{d.drug}</strong> · cosine {d.cosine.toFixed(2)}</div>
                    }}
                  />
                  {PROFILE_POINTS.map((p) => (
                    <Scatter key={`p${p.lane}`} data={[p]} fill={LANE_COLORS[p.lane]} shape="diamond" isAnimationActive={false}>
                      <ZAxis range={[220, 220]} />
                    </Scatter>
                  ))}
                  {state.matches
                    ? PROFILES.map((p) => (
                        <Scatter key={`d${p.lane}`} data={drugs.filter((d) => d.lane === p.lane)} fill={LANE_COLORS[p.lane]} fillOpacity={0.55} isAnimationActive={false}>
                          <LabelList dataKey="drug" position="right" style={{ fontSize: 10, fill: 'var(--muted-foreground)' }} />
                        </Scatter>
                      ))
                    : null}
                </ScatterChart>
              </ChartContainer>
              <p className="text-[0.6875rem] text-muted-foreground">◆ profile vector · ● nearest compounds by cosine similarity</p>
            </div>
            <Trace stage="embedding" title="Embedding job" maxH="max-h-56" />
          </div>
          <div className="space-y-3 lg:col-span-4">
            {PROFILES.map((p) => (
              <div key={p.lane} className="rounded-lg bg-card p-3 text-xs ring-1 ring-border backdrop-blur-md">
                <p className="flex items-center gap-1.5 font-medium"><span className="size-2 rounded-full" style={{ background: LANE_COLORS[p.lane] }} /> {p.name}</p>
                {state.matches ? (
                  <ul className="mt-1.5 space-y-0.5">
                    {MATCHES.filter((m) => m.lane === p.lane).map((m) => (
                      <li key={m.drug} className="flex justify-between gap-2"><span>{m.drug}</span><span className="text-muted-foreground tabular-nums">{m.cosine.toFixed(2)}</span></li>
                    ))}
                  </ul>
                ) : (
                  <p className="mt-1.5 text-muted-foreground">Searching…</p>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

/* ----------------------------------------------------- 04 research & ranking */

export function CandidatesPage({ go }: { go: Go }) {
  const { state, weights, setWeights } = useRun()
  const ranked = rank(CANDIDATES, weights)
  return (
    <div className="mx-auto max-w-[1440px] space-y-3 text-sm">
      <StageHeader
        step="04 · Research & ranking"
        title="Rank for this patient."
        description="A research agent with open search checks evidence, interactions with current medication, cost, availability in Canada and patient burden, then ranks the matches."
      />
      {state.stages.research === 'pending' ? (
        <EmptyStage after="DRKG embedding" onGo={() => go('case')} />
      ) : (
        <div className="grid gap-3 lg:grid-cols-12">
          <div className="space-y-3 lg:col-span-8">
            {state.candidates ? (
              <>
                <div className="flex flex-wrap gap-x-5 gap-y-2 rounded-lg bg-card px-4 py-3 ring-1 ring-border backdrop-blur-md">
                  <span className="text-xs text-muted-foreground">Rank by</span>
                  {CRITERIA.map((c) => (
                    <label key={c.key} className="flex items-center gap-2 text-xs" title={c.hint}>
                      <Switch checked={weights[c.key]} onCheckedChange={(v) => setWeights({ ...weights, [c.key]: v })} />
                      {c.label}
                    </label>
                  ))}
                </div>
                <div className="overflow-x-auto rounded-lg bg-card ring-1 ring-border backdrop-blur-md">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead className="w-8">#</TableHead>
                        <TableHead>Candidate</TableHead>
                        <TableHead>Delivery</TableHead>
                        {CRITERIA.map((c) => (
                          <TableHead key={c.key} title={c.label} className={cn('text-right', !weights[c.key] && 'opacity-40')}>{c.short}</TableHead>
                        ))}
                        <TableHead className="text-right">Overall</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {ranked.map((c, i) => (
                        <TableRow key={c.drug}>
                          <TableCell className="text-muted-foreground tabular-nums">{i + 1}</TableCell>
                          <TableCell>
                            <div className="flex items-center gap-2"><span className="size-2 rounded-full" style={{ background: LANE_COLORS[c.lane] }} /><span className="font-medium">{c.drug}</span></div>
                            <div className="max-w-[14rem] text-xs whitespace-normal text-muted-foreground">{c.cls}</div>
                          </TableCell>
                          <TableCell className="text-xs whitespace-normal">
                            <div>BBB alone: {c.bbbAlone}</div>
                            <div className="text-[#a35b1d]">MRgFUS: {c.withFus}</div>
                          </TableCell>
                          {CRITERIA.map((k) => (
                            <TableCell key={k.key} className={cn('text-right tabular-nums', !weights[k.key] && 'opacity-40')}>{c.scores[k.key]}</TableCell>
                          ))}
                          <TableCell className="text-right"><span className="font-brand text-lg tabular-nums">{c.overall}</span></TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
                <div className="rounded-lg bg-card px-4 py-3 text-xs ring-1 ring-border backdrop-blur-md">
                  <p className="mb-1.5 text-muted-foreground">Excluded for this patient</p>
                  <ul className="space-y-0.5">
                    {EXCLUDED.map((e) => <li key={e.drug}><strong className="font-medium">{e.drug}</strong> — {e.reason}</li>)}
                  </ul>
                </div>
              </>
            ) : (
              <Card className="[--card-spacing:--spacing(6)]">
                <CardContent className="flex items-center gap-2 text-muted-foreground"><Loader2 className="size-4 animate-spin" aria-hidden /> Researching candidates…</CardContent>
              </Card>
            )}
          </div>
          <div className="lg:col-span-4">
            <Trace stage="research" title="Research agent" maxH="max-h-[34rem]" />
          </div>
        </div>
      )}
    </div>
  )
}

/* ----------------------------------------------------------------- 05 report */

export function ReportPage({ go }: { go: Go }) {
  const { state, weights, date } = useRun()
  return (
    <div className="mx-auto max-w-[1440px] space-y-3 text-sm">
      <StageHeader
        step="05 · Report"
        title="The case for each candidate."
        description="Cited, patient-specific, and ready to bring to the neurologist."
      />
      {!state.report ? (
        <EmptyStage after="research & ranking" onGo={() => go('case')} />
      ) : (
        <div className="mx-auto max-w-4xl rounded-xl bg-card p-6 ring-1 ring-border backdrop-blur-md">
          <Report patient={SAMPLE_PATIENT} weights={weights} date={date} />
        </div>
      )}
    </div>
  )
}

export { Badge }

