import { spawn } from 'node:child_process'
import { writeFileSync, mkdtempSync } from 'node:fs'
import { join } from 'node:path'
import { tmpdir } from 'node:os'

const [base, out] = process.argv.slice(2)
const port = 9337
const chrome = spawn('C:/Program Files/Google/Chrome/Application/chrome.exe', [
  '--headless=new', `--remote-debugging-port=${port}`, '--window-size=1440,900',
  '--use-angle=swiftshader', '--enable-unsafe-swiftshader', `--user-data-dir=${mkdtempSync(join(tmpdir(), 'cdp-man-'))}`, 'about:blank',
], { stdio: 'ignore' })
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
let targets
for (let i = 0; i < 40; i++) {
  try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); break } catch { await sleep(250) }
}
const ws = new WebSocket(targets.find((t) => t.type === 'page').webSocketDebuggerUrl)
await new Promise((r) => ws.addEventListener('open', r))
let id = 0
const pending = new Map()
ws.addEventListener('message', (e) => {
  const m = JSON.parse(e.data)
  if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id) }
  if (m.method === 'Runtime.exceptionThrown') console.log('EXC', JSON.stringify(m.params.exceptionDetails).slice(0, 300))
  if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') console.log('CONSOLE', m.params.args.map((a) => a.value ?? a.description).join(' ').slice(0, 300))
})
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })) })
const js = async (expression) => (await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })).result?.result?.value
const click = (text, sel = 'button') => js(`(() => { const b = [...document.querySelectorAll('${sel}')].find((b) => b.textContent.trim().includes(${JSON.stringify(text)}) && !b.disabled); if (!b) return 'missing'; b.click(); return 'ok' })()`)
const status = () => js(`[...document.querySelectorAll('[data-slot=sidebar-menu-button]')].slice(1, 7).map((b) => b.textContent.trim().replace(/^\\d+/, '').slice(0, 10) + ':' + (b.querySelector('[aria-label]')?.getAttribute('aria-label') ?? '?')).join('  ')`)
const report = async (tag) => console.log(tag.padEnd(26), (await js('location.pathname')).padEnd(18), await status())
let n = 0
const shot = async (name) => {
  const r = await send('Page.captureScreenshot', { format: 'png' })
  writeFileSync(`${out}-${++n}-${name}.png`, Buffer.from(r.result.data, 'base64'))
}

await send('Page.enable'); await send('Runtime.enable')
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false })
await send('Page.navigate', { url: `${base}/home` })
await sleep(3500)
await js(`document.querySelector('.dither-container').style.display = 'none'`)
console.log('rail present:', await js(`!!document.querySelector('ol[aria-label="Pipeline progress"]')`))

console.log('start', await click('Run patient analysis')); await sleep(1000); await report('analysis running')
await sleep(9000); await report('analysis finished (wait)')
console.log('nav buttons:', await js(`[...document.querySelectorAll('nav[aria-label="Workflow steps"] button')].map(b => b.textContent.trim()).join(' | ')`))
await shot('analysis-paused')

console.log('run next', await click('Run profile agents', 'nav button')); await sleep(800); await report('profiles started')
await sleep(9000); await report('profiles finished (wait)')
console.log('to embedding via sidebar', await click('DRKG embedding', '[data-slot=sidebar-menu-button]')); await sleep(800); await report('embedding page')
console.log('empty state:', await js(`document.querySelector('.eyebrow + p, [data-slot=card] p.eyebrow')?.parentElement?.textContent?.slice(0, 120)`))
await shot('embedding-ready')
console.log('run here', await click('Run drkg embedding')); await sleep(600)
console.log('finish', await click('Finish this step')); await sleep(600); await report('embedding finished')
await sleep(3000); await report('still paused after 3 s')
console.log('run next', await click('Run research & ranking', 'nav button')); await sleep(400)
console.log('finish', await click('Finish this step')); await sleep(600)
console.log('run next', await click('Run report', 'nav button')); await sleep(400)
console.log('finish', await click('Finish this step')); await sleep(800); await report('report done')
await shot('report')

ws.close(); chrome.kill(); process.exit(0)

