412	const link = (gl: WebGL2RenderingContext, fragmentSource: string): Program | null => {
413	  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
414	  const fragment = compile(gl, gl.FRAGMENT_SHADER, fragmentSource);
415	  const program = gl.createProgram();
416	  if (!vertex || !fragment || !program) return null;
417	  gl.attachShader(program, vertex);
418	  gl.attachShader(program, fragment);
419	  gl.linkProgram(program);
420	  gl.deleteShader(vertex);
421	  gl.deleteShader(fragment);
422	  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
423	    gl.deleteProgram(program);
424	    return null;
425	  }
426	  const uniforms: Record<string, WebGLUniformLocation | null> = {};
427	  const count = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
428	  for (let i = 0; i < count; i++) {
429	    const info = gl.getActiveUniform(program, i);
430	    if (!info) continue;
431	    const name = info.name.replace(/\[0\]$/, '');
432	    uniforms[name] = gl.getUniformLocation(program, name);
433	  }
434	  return { program, uniforms };
435	};
