437	const createTarget = (gl: WebGL2RenderingContext, count: number): Target => {
438	  const textures = Array.from({ length: count }, () => {
439	    const texture = gl.createTexture();
440	    gl.bindTexture(gl.TEXTURE_2D, texture);
441	    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
442	    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
443	    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
444	    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
445	    return texture;
446	  });
447	  return { textures, framebuffer: gl.createFramebuffer(), width: 0, height: 0 };
448	};
