450	const sizeTarget = (gl: WebGL2RenderingContext, target: Target, width: number, height: number) => {
451	  if (target.width === width && target.height === height) return;
452	  target.width = width;
453	  target.height = height;
454	  gl.bindFramebuffer(gl.FRAMEBUFFER, target.framebuffer);
455	  target.textures.forEach((texture, i) => {
456	    gl.bindTexture(gl.TEXTURE_2D, texture);
457	    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, width, height, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
458	    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0 + i, gl.TEXTURE_2D, texture, 0);
459	  });
460	  gl.bindFramebuffer(gl.FRAMEBUFFER, null);
461	};
