463	const buildAtlas = (gl: WebGL2RenderingContext, characters: string, fontFamily: string): Atlas => {
464	  const list = [...new Set([...characters].filter(char => char !== '\n' && char !== '\r'))];
465	  if (!list.length) list.push(' ');
466	  const font = `300 ${Math.round(ATLAS_CELL_H * FONT_SCALE)}px ${fontFamily}`;
467	  const columns = Math.min(ATLAS_COLUMNS, list.length);
468	  const rows = Math.ceil(list.length / columns);
469	  const canvas = document.createElement('canvas');
470	  canvas.width = ATLAS_CELL_W * columns;
471	  canvas.height = ATLAS_CELL_H * rows;
472	  const context = canvas.getContext('2d');
473	  if (context) {
474	    context.font = font;
475	    context.textAlign = 'center';
476	    context.textBaseline = 'middle';
477	    context.fillStyle = '#fff';
478	    list.forEach((char, index) => {
479	      const column = index % columns;
480	      const row = Math.floor(index / columns);
481	      context.fillText(char, column * ATLAS_CELL_W + ATLAS_CELL_W / 2, row * ATLAS_CELL_H + ATLAS_CELL_H / 2 + 3);
482	    });
483	  }
484	  const texture = gl.createTexture();
485	  gl.bindTexture(gl.TEXTURE_2D, texture);
486	  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
487	  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, gl.RGBA, gl.UNSIGNED_BYTE, canvas);
488	  gl.generateMipmap(gl.TEXTURE_2D);
489	  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
490	  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
491	  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
492	  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
493	  return { texture, count: list.length, grid: [columns, rows] };
