    g.setAttribute('d', d)
    c.setAttribute('d', d)
    g.style.opacity = '1'
    const len = c.getTotalLength()
    const seg = Math.min(140, len * 0.3)
    c.style.strokeDasharray = `${seg} ${len + seg}`
